let liveSubscribe=null,liveUnsubs=[],liveSessionId='',liveExam=null,liveSession=null,liveAggregate=null,liveAnswer=null,liveResultUnsub=null;
function stopLive(){for(const unsubscribe of liveUnsubs)unsubscribe();liveUnsubs=[];liveResultUnsub=null;}
function watchLive(path,callback){if(!demo){if(!liveSubscribe){toast('A conexão de tempo real ainda não está pronta.');return;}const unsubscribe=liveSubscribe(path,callback,e=>toast('Não foi possível acompanhar ao vivo: '+friendly(e)));liveUnsubs.push(unsubscribe);return unsubscribe;}let previous='';const tick=()=>{const parts=path.split('/'),v=parts.length===2?demoDB.sessions?.[parts[1]]?.session:demoDB.sessions?.[parts[1]]?.aggregates?.[parts[3]];const serialized=JSON.stringify(v);if(previous!==serialized){previous=serialized;callback(v||null);}};tick();const timer=setInterval(tick,300);const unsubscribe=()=>clearInterval(timer);liveUnsubs.push(unsubscribe);return unsubscribe;}
function chartOptions(selected){return[['bars','Barras'],['pie','Pizza'],['dots','Bolinhas'],['wordcloud','Nuvem de palavras']].map(([value,label])=>`<option value="${value}" ${selected===value?'selected':''}>${label}</option>`).join('');}
