async function teacherLive(sessionId){stopLive();const r=await call('getLiveSession',{sessionId,teacher:true});liveSessionId=sessionId;liveExam=r.exam;liveSession=r.session;localStorage.setItem(`conexoes-sessao-${config.firebase.projectId}-${r.session.examId}`,sessionId);renderTeacherLive();let signature='';watchLive(`liveSessions/${sessionId}`,s=>{if(!s)return;const sig=[s.questionId,s.status,s.showResults].join('|');liveSession=s;if($('live-participants'))$('live-participants').textContent=s.participantCount||0;if(signature&&signature!==sig)renderTeacherLive();signature=sig;});}
function renderTeacherLive(){if(liveResultUnsub)liveResultUnsub();const s=liveSession,q=liveExam.questions[s.currentIndex],sessionId=liveSessionId;const share=new URL(location.href);share.search='';share.searchParams.set('sessao',sessionId);app.innerHTML=`<button class="outline" id="leave-live">Voltar às avaliações</button><span class="eyebrow" style="display:block;margin-top:22px">Quiz ao vivo · ${esc(liveExam.subject)}</span><h1 style="font-size:40px">${esc(liveExam.title)}</h1><div class="card"><p><strong>Código:</strong> ${esc(sessionId)}</p><label for="live-link">Link para os alunos</label><input id="live-link" readonly value="${esc(share.href)}"><p>${esc(liveExam.group)} · <strong id="live-participants">${s.participantCount||0}</strong> participantes ingressaram · <strong id="live-response-count">0</strong> respostas nesta pergunta</p><p class="muted">Cada aluno usa a conta Google e precisa de matrícula ativa na disciplina e turma. Participantes não significa presença simultânea.</p></div><div class="card"><span class="pill">Pergunta ${s.currentIndex+1} de ${liveExam.questions.length} · ${{lobby:'Aguardando abertura',open:'Recebendo respostas',closed:'Respostas encerradas',ended:'Sessão encerrada'}[s.status]}</span><h2 class="pre">${esc(q.prompt)}</h2>${renderCodeBlock(q)}${q.options?`<ol type="A">${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol>`:'<p>Resposta curta em texto, até 200 caracteres.</p>'}<div class="actions">${s.status!=='ended'?`<button id="live-open" ${s.status==='open'?'disabled':''}>Abrir pergunta</button><button id="live-close" class="secondary" ${s.status!=='open'?'disabled':''}>Encerrar respostas</button><button id="live-results" class="outline">${s.showResults?'Ocultar':'Mostrar'} resultados</button><button id="live-prev" class="outline" ${s.currentIndex===0?'disabled':''}>Anterior</button><button id="live-next" class="outline" ${s.currentIndex===liveExam.questions.length-1?'disabled':''}>Próxima pergunta</button><button id="live-end" class="danger">Finalizar sessão</button>`:''}</div>${s.status==='ended'?`<label for="live-history">Consultar resultados de outra pergunta</label><select id="live-history">${liveExam.questions.map((x,i)=>`<option value="${i}" ${i===s.currentIndex?'selected':''}>Pergunta ${i+1}</option>`).join('')}</select>`:''}<div id="live-chart-output" aria-live="polite"></div><details><summary>Respostas individuais — somente professor</summary><button id="live-individual" class="outline">Consultar respostas individuais</button><div id="live-individual-output"></div></details></div>`;on('leave-live',()=>{stopLive();examList();});for(const[action,button]of[['open','live-open'],['close','live-close'],['previous','live-prev'],['next','live-next'],['end','live-end']])on(button,()=>call('controlLiveSession',{sessionId,action}));on('live-results',()=>call('controlLiveSession',{sessionId,action:s.showResults?'hide':'show'}));on('live-individual',async()=>{const r=await call('liveResponses',{sessionId,questionId:q.id});$('live-individual-output').innerHTML=`<table><thead><tr><th>Aluno</th><th>Resposta</th></tr></thead><tbody>${r.responses.map(row=>`<tr><td>${esc(row.name)}</td><td class="pre">${esc(q.options?(q.type==='multiple'?row.answer.map(n=>'ABCDEF'[n]+') '+q.options[n]).join('; '):'ABCDEF'[row.answer]+') '+q.options[row.answer]):row.answer)}</td></tr>`).join('')}</tbody></table>`;});if($('live-history'))$('live-history').onchange=()=>{const i=Number($('live-history').value);liveSession={...liveSession,currentIndex:i,questionId:liveExam.questions[i].id};renderTeacherLive();};liveAggregate=emptyAggregate(q);paintLiveChart();liveResultUnsub=watchLive(`liveSessions/${sessionId}/results/${q.id}`,a=>{if(liveSession?.questionId!==q.id)return;liveAggregate=a||emptyAggregate(q);paintLiveChart();});}
function paintLiveChart(){if(!$('live-chart-output'))return;const q=liveExam.questions[liveSession.currentIndex],a=liveAggregate||emptyAggregate(q);$('live-response-count').textContent=a.responseCount||0;if(!liveSession.showResults&&liveSession.status!=='ended'){$('live-chart-output').innerHTML='<div class="notice">Resultados ocultos. Use Mostrar resultados quando desejar apresentar a distribuição.</div>';return;}$('live-chart-output').innerHTML=renderLiveChart(q,a,liveChart(liveExam,q),liveExam.presentation?.value||'count');}
function renderLiveChart(q,a,type,value){const series=liveSeries(q,a,type),total=a.responseCount||0,colors=['#176f60','#d36c36','#3d70b7','#8b54a4','#b08925','#3d8a9d'];const label=x=>value==='percent'?`${(type==='pie'?x.sharePercent??x.percent:x.percent).toLocaleString('pt-BR',{maximumFractionDigits:1})}%`:String(x.count);if(!total)return'<div class="notice">Nenhuma resposta recebida ainda.</div>';const note=type==='wordcloud'?'Cada palavra conta no máximo uma vez por resposta. Uma resposta pode conter várias palavras.':type==='pie'&&q.type==='multiple'?'Pizza: distribuição de todas as marcações. As porcentagens representam a parcela das marcações, não dos participantes.':q.type==='multiple'?'Uma pessoa pode marcar várias alternativas; em barras/bolinhas, as porcentagens por alternativa usam o total de respondentes e podem somar mais de 100%.':'Cada participante responde uma vez por pergunta.';let graphic='';if(type==='wordcloud'){const top=Math.max(1,...series.map(x=>x.count));graphic=`<div class="word-cloud">${series.map((x,i)=>`<span style="font-size:${18+x.count/top*34}px;color:${colors[i%colors.length]}" title="${esc(x.label)}: ${label(x)}">${esc(x.label)} <small>${label(x)}</small></span>`).join('')}</div>`;}else if(type==='bars'){const max=Math.max(1,...series.map(x=>x.count));graphic=series.map((x,i)=>`<div class="live-bar"><div>${esc(x.label)} <strong>${label(x)}</strong></div><div class="bar-track"><span style="width:${x.count/max*100}%;background:${colors[i%colors.length]}"></span></div></div>`).join('');}else if(type==='dots'){graphic=series.map((x,i)=>`<div class="dot-row"><strong>${esc(x.label)} · ${label(x)}</strong><div class="dots" aria-label="${x.count} respostas">${Array(Math.min(40,x.count)).fill(`<span style="background:${colors[i%colors.length]}"></span>`).join('')}${x.count>40?`<b>+${x.count-40}</b>`:''}</div></div>`).join('');graphic+='<p class="muted">Cada bolinha representa uma resposta/marcação; até 40 por alternativa, com o restante indicado por número.</p>';}else{let angle=0;const marks=series.reduce((s,x)=>s+x.count,0);const paths=series.map((x,i)=>{if(!x.count)return'';const delta=x.count/marks*360;if(delta>=359.999)return`<circle cx="110" cy="110" r="96" fill="${colors[i%colors.length]}"/>`;const begin=angle*Math.PI/180,end=(angle+delta)*Math.PI/180;const d=`M110,110 L${110+96*Math.sin(begin)},${110-96*Math.cos(begin)} A96,96 0 ${delta>180?1:0} 1 ${110+96*Math.sin(end)},${110-96*Math.cos(end)} Z`;angle+=delta;return`<path d="${d}" fill="${colors[i%colors.length]}"/>`;}).join('');graphic=`<div class="pie-layout"><svg viewBox="0 0 220 220" role="img" aria-label="Distribuição de respostas em pizza">${paths}</svg><ul>${series.map((x,i)=>`<li><span class="legend-dot" style="background:${colors[i%colors.length]}"></span>${esc(x.label)} <strong>${label(x)}</strong></li>`).join('')}</ul></div>`;}return`<h3>Distribuição das respostas</h3><p class="muted">${total} respondentes. ${note}</p>${graphic}<details><summary>Ver dados em tabela</summary><table><thead><tr><th>Resposta</th><th>Contagem</th><th>Porcentagem${type==='pie'?' das marcações':''}</th></tr></thead><tbody>${series.map(x=>`<tr><td>${esc(x.label)}</td><td>${x.count}</td><td>${(type==='pie'?x.sharePercent??x.percent:x.percent).toLocaleString('pt-BR',{maximumFractionDigits:1})}%</td></tr>`).join('')}</tbody></table></details>`;}
async function joinLive(sessionId){stopLive();const r=await call('getLiveSession',{sessionId});liveSessionId=sessionId;liveExam=r.exam;liveSession=r.session;liveAnswer=null;renderStudentLive(r.response);let signature=[r.session.questionId,r.session.status].join('|');watchLive(`liveSessions/${sessionId}`,s=>{if(!s)return;const next=[s.questionId,s.status].join('|');liveSession=s;if(next!==signature){signature=next;guard(()=>joinLive(sessionId))();}});}
function renderStudentLive(response){const s=liveSession,q=liveExam.questions[s.currentIndex];app.innerHTML=`<button id="live-student-back" class="outline">Sair do quiz</button><span class="eyebrow" style="display:block;margin-top:22px">Quiz ao vivo · ${esc(liveExam.subject)}</span><h1 style="font-size:38px">${esc(liveExam.title)}</h1><div class="card"><span class="pill">Pergunta ${s.currentIndex+1} de ${liveExam.questions.length}</span><h2 class="pre">${esc(q.prompt)}</h2>${renderCodeBlock(q)}${s.status==='ended'?'<div class="notice">Sessão encerrada. Obrigado por participar.</div>':response?'<div class="notice">Resposta registrada. Aguarde a próxima pergunta do professor.</div>':s.status!=='open'?'<div class="notice">Aguarde o professor abrir esta pergunta.</div>':`${q.options?q.options.map((o,i)=>`<label class="option"><input ${q.type==='multiple'?'type="checkbox"':'type="radio" name="live-choice"'} data-live-answer="${i}"><b>${'ABCDEF'[i]}</b><span>${esc(o)}</span></label>`).join(''):`<label for="live-text">Resposta curta (até 200 caracteres)</label><input id="live-text" maxlength="200" autocomplete="off">`}${q.type==='multiple'?'<p class="muted">Você pode selecionar mais de uma alternativa. Enviar sem marcar registra nenhuma alternativa.</p>':''}<button id="live-send">Enviar resposta</button><p class="muted">Uma resposta por pergunta. Após enviar, não é possível alterar. Envie antes do encerramento pelo professor.</p>`}</div>`;on('live-student-back',()=>{stopLive();studentHome();});on('live-send',async()=>{let answer;if(q.type==='open')answer=$('live-text').value;else if(q.type==='multiple')answer=[...document.querySelectorAll('[data-live-answer]:checked')].map(x=>Number(x.dataset.liveAnswer));else{const selected=document.querySelector('[data-live-answer]:checked');if(!selected)throw Error('Selecione uma alternativa.');answer=Number(selected.dataset.liveAnswer);}if(q.type==='open'&&!answer.trim())throw Error('Digite sua resposta.');await call('submitLiveResponse',{sessionId:liveSessionId,questionId:q.id,answer});await joinLive(liveSessionId);});}

