let user=null,api=null,demo=false,exam=null,qs=[],attempt=null,answers={},pending=[],revision=0,savedRevision=0,qindex=0,active=false,saving=false,flushing=null,saveTimer=null,teacherView=false,currentDetail=null,rows=[],cursor=null,examRows=[],examCursor=null,editing=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uuid=()=>crypto.randomUUID(),$=id=>document.getElementById(id),stamp=()=>new Date().toISOString();
const date=v=>v?new Date(v._seconds?v._seconds*1000:v.seconds?v.seconds*1000:v).toLocaleString('pt-BR'):'—';
const day=v=>v?v.split('-').reverse().join('/'):'—';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const guard=fn=>async e=>{const b=e?.currentTarget;if(b?.tagName==='BUTTON')b.disabled=true;try{await fn(e);}catch(err){toast(friendly(err));}finally{if(b)b.disabled=false;}};
const on=(id,fn)=>{if($(id))$(id).onclick=guard(fn);};
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').style.display='none',6500);}
function friendly(e){console.error(e);return !navigator.onLine?'Sem conexão. As alterações pendentes ficam neste aparelho.':e?.message||'Não foi possível concluir. Tente novamente.';}
