function header(){account.innerHTML=user?`<span>${esc(user.displayName||user.email)}</span>${demo?`<span class="pill bad">DEMONSTRAÇÃO</span><select id="demo-role" aria-label="Perfil de demonstração" style="width:180px;font-size:13px">${[['teacher','Professor aprovado','prof-demo'],['pending','Professor pendente','prof-pendente'],['student','Estudante','aluno-demo'],['staff','Equipe de acompanhamento','equipe-demo'],['admin','Administrador','admin-demo']].map(([v,label,uid])=>`<option value="${v}" ${user.uid===uid?'selected':''}>${label}</option>`).join('')}</select>`:''}${profile?.status==='active'&&!active||adminView?'<button class="outline" id="nav-courses">Cursos</button><button class="outline" id="nav-notices">Avisos</button><button class="outline" id="nav-academic">Acompanhamento</button><button class="outline" id="nav-bank">Banco de questões</button><button class="outline" id="nav-payments">Pagamentos e renovação</button>':''}<button class="outline" id="logout">Sair</button>`:'';if((!teacherView||myModuleFeatures?.questionBank===false)&&$('nav-bank'))$('nav-bank').remove();if((profile?.role==='student'||teacherView&&myModuleFeatures?.tracking===false)&&!adminView&&$('nav-academic'))$('nav-academic').remove();on('nav-academic',()=>academicHub());on('nav-courses',()=>coursesPanel());on('nav-notices',()=>noticesPanel());on('nav-bank',()=>bankPanel(false));on('nav-payments',()=>billingPanel());if($('demo-role'))$('demo-role').onchange=guard(()=>switchDemo($('demo-role').value));on('logout',async()=>{if(active){toast('Entregue a avaliação antes de sair. Em caso de imprevisto, avise o professor.');return;}if(demo){location.reload();return;}await window.firebaseSignOut();});}
