function landing(){active=false;document.body.classList.remove('active-exam');app.innerHTML=`<section class="hero"><div><span class="eyebrow">Avaliações para todas as disciplinas</span><h1>Uma plataforma.<br>Muitas descobertas.</h1><p class="lead">Crie questões, acompanhe as respostas e transforme a avaliação em uma oportunidade de aprender.</p><div class="grid metrics"><div class="metric"><strong>Criar</strong><small>questões e critérios</small></div><div class="metric"><strong>Aplicar</strong><small>por data e turma</small></div><div class="metric"><strong>Orientar</strong><small>com devolutivas</small></div></div><button id="login">Entrar com Google</button><p class="muted">Professores e estudantes usam a mesma entrada.</p></div><div class="hero-art"><span class="eyebrow" style="color:#c5e5ab">CADA TURMA, UM NOVO PERCURSO</span><h2>Conhecimento<br>em construção.</h2><div class="nodes"><div class="node">Criar</div><span class="link"></span><div class="node">Responder</div><span class="link"></span><div class="node">Revisar</div></div><span class="chip">Qualquer disciplina</span><span class="chip">Pelo celular</span><span class="chip">Conceito ou nota</span></div></section><section class="card" style="margin-top:36px"><h2>Conheça o ambiente</h2><p>O professor cadastra a avaliação e compartilha seu código ou link. Os estudantes respondem pelo celular; a correção, as ocorrências e os resultados ficam organizados por avaliação.</p>${!config.enabled?'<div class="notice warning">Firebase ainda não conectado. A demonstração usa dados fictícios neste navegador e é reiniciada ao recarregar.</div>':''}<div class="actions"><button class="secondary" id="demo-teacher">Testar painel do professor</button><button class="outline" id="demo-student">Testar como estudante</button><button class="outline" id="demo-admin">Testar administrador</button></div><p class="muted">Durante a tentativa, ações de copiar e colar são bloqueadas e eventos de visibilidade podem ser registrados. Capturas de tela não podem ser impedidas ou detectadas com segurança.</p></section>`;on('login',async()=>{if(!config.enabled)throw Error('Configure o Firebase conforme o guia incluído no pacote.');await window.firebaseLogin();});on('demo-teacher',()=>startDemo(true));on('demo-student',()=>startDemo(false));on('demo-admin',()=>startDemo('admin'));}
let bulkSelected=new Set(),importPreview=null,importBusy=false;
function eligibleVisibleStudents(){const f=($('admin-filter')?.value||'').toLowerCase(),institutionId=$('bulk-institution')?.value,campusId=$('bulk-campus')?.value;return adminRows.filter(p=>p.role==='student'&&p.status==='pending'&&p.institutionId===institutionId&&p.campusId===campusId&&(p.name+' '+p.email+' '+p.role+' '+p.status+' '+campusName(p.campusId)).toLowerCase().includes(f));}
function bulkControls(){return `<div class="notice"><h3>Aprovar alunos em lote</h3>${scopeSelects('bulk')}<p>Selecione os alunos pendentes do campus escolhido. Professores continuam sendo aprovados individualmente, com atribuição de disciplinas.</p><div class="actions"><button class="secondary" id="bulk-all">Selecionar pendentes exibidos</button><button class="outline" id="bulk-none">Limpar seleção</button><button id="bulk-review">Conferir aprovação (<span id="bulk-count">0</span>)</button></div><div id="bulk-result" role="status"></div></div>`;}
function bindBulk(){bulkSelected.clear();bindScope('bulk',{},()=>{bulkSelected.clear();paintAdminUsers();});on('bulk-all',()=>{bulkSelected.clear();for(const p of eligibleVisibleStudents().slice(0,100))bulkSelected.add(p.uid);paintAdminUsers();});on('bulk-none',()=>{bulkSelected.clear();paintAdminUsers();});on('bulk-review',()=>{const selected=eligibleVisibleStudents().filter(p=>bulkSelected.has(p.uid));if(!selected.length)throw Error('Selecione alunos pendentes do campus escolhido.');if(selected.length>100)throw Error('Limite de 100 alunos por lote.');const institutionId=$('bulk-institution').value,campusId=$('bulk-campus').value;app.innerHTML=`<button id="bulk-back" class="outline">Voltar sem aprovar</button><h1 style="font-size:40px">Conferir ${selected.length} aprovações.</h1><p>${esc(institutionName(institutionId))} · ${esc(campusName(campusId))}</p><div class="card"><p>Serão aprovados somente os cadastros ainda pendentes e compatíveis com este campus no momento da confirmação. Matrículas preparadas por importação serão vinculadas quando compatíveis.</p>${selected.map(p=>`<p><strong>${esc(p.name)}</strong> · ${esc(p.email)}</p>`).join('')}<button id="bulk-confirm">Confirmar aprovação dos ${selected.length} alunos</button><div id="bulk-result" role="status"></div></div>`;on('bulk-back',()=>adminPanel());on('bulk-confirm',async()=>{const r=await call('bulkApproveStudents',{uids:selected.map(p=>p.uid),institutionId,campusId});$('bulk-result').innerHTML=`<div class="notice">${r.results.filter(x=>x.status==='approved').length} aprovados; ${r.results.filter(x=>x.status!=='approved').length} ignorados após revalidação.</div>${r.results.map(x=>`<p>${esc(selected.find(p=>p.uid===x.uid)?.name||x.uid)}: ${esc(x.message)}</p>`).join('')}<button id="bulk-finish" class="secondary">Voltar à administração</button>`;$('bulk-confirm').hidden=true;on('bulk-finish',()=>adminPanel());});});}
function importStorageKey(){return `conexoes-import-${config.firebase.projectId}-${demo?'demo-':''}${user.uid}-${selectedSubjectId}`;}
function importControls(){return `<details class="card" id="json-import"><summary>Importar alunos do Google Classroom (JSON)</summary><p>Selecione o arquivo <strong>Class data.json</strong>. Somente nome e e-mail da lista de alunos serão utilizados. Publicações, professores e atividades não são enviados ao servidor.</p><label for="json-group">Turma de destino nesta disciplina</label><input id="json-group" maxlength="80"><label for="json-file">Arquivo JSON (até 5 MB; até 300 alunos)</label><input id="json-file" type="file" accept=".json,application/json"><div class="actions"><button id="json-preview" class="secondary">Carregar e conferir prévia</button><button id="json-resume" class="outline">Retomar última importação</button>${demo?'<button id="json-example" class="outline">Usar JSON fictício de exemplo</button>':''}</div><div id="json-output"></div></details>`;}
function bindImport(){importPreview=null;on('json-preview',async()=>{const file=$('json-file').files[0];if(!file)throw Error('Escolha um arquivo JSON.');if(file.size>5*1024*1024)throw Error('O arquivo deve ter até 5 MB.');let input;try{input=JSON.parse(await file.text());}catch{throw Error('O arquivo não contém JSON válido.');}await previewImport(input);});on('json-example',()=>{if(!$('json-group').value)$('json-group').value='Turma de exemplo';return previewImport({students:[{profile:{name:{fullName:'Estudante de demonstração'},emailAddress:'aluno@exemplo.test'}},{profile:{name:{fullName:'Novo estudante fictício'},emailAddress:'novo@exemplo.test'}},{profile:{name:{fullName:'Primeiro acesso fictício'},emailAddress:'cadastro@exemplo.test'}},{profile:{name:{fullName:'Registro repetido'},emailAddress:'novo@exemplo.test'}}]});});on('json-resume',async()=>{const importId=localStorage.getItem(importStorageKey());if(!importId)throw Error('Nenhuma importação guardada neste navegador para esta disciplina.');const job=await call('getRosterImport',{importId});importPreview={importId,...job};paintImport();});}
async function previewImport(input){if(importBusy)throw Error('Aguarde a operação atual.');const group=$('json-group').value.trim();if(!group)throw Error('Informe a turma de destino.');const rows=parseClassroomRoster(input);$('json-output').textContent='Consultando matrículas e preparando a prévia…';importPreview=await call('previewRosterImport',{subjectId:selectedSubjectId,group,rows});localStorage.setItem(importStorageKey(),importPreview.importId);paintImport();}
function paintImport(report=null){const p=importPreview,results=report?.results||Object.values(p.results||{}),done=report?.done||p.status==='complete';$('json-output').innerHTML=`<h3>${done?'Resultado da importação':'Confira antes de importar'}</h3><p>Disciplina: ${esc(catalog.subjects.find(s=>s.id===selectedSubjectId)?.name)} · Turma: ${esc(p.group)}</p><div class="notice">${p.rows.length} registros. ${done?`${results.filter(x=>x.action==='enroll').length} matrículas criadas; ${results.filter(x=>x.action==='wait').length} aguardando cadastro/aprovação; ${results.filter(x=>x.action==='skip').length} ignorados.`:'Nenhuma matrícula é criada antes da confirmação. A prévia expira em 15 minutos; dados são revalidados ao gravar.'}</div><div class="question-table"><table><thead><tr><th>Aluno</th><th>E-mail</th><th>Situação</th></tr></thead><tbody>${p.rows.map(row=>{const result=results.find(x=>x.index===row.index);return `<tr><td>${esc(row.name||'Sem nome')}</td><td>${esc(row.email)}</td><td>${esc(result?.message||row.label)}</td></tr>`;}).join('')}</tbody></table></div>${!done?'<button id="json-confirm">Confirmar importação</button>':''}<p id="json-progress" role="status">${results.length?`${results.length} de ${p.rows.length} processados.`:''}</p>`;on('json-confirm',async()=>{if(importBusy)return;importBusy=true;const button=$('json-confirm');try{let r;do{r=await call('confirmRosterImport',{importId:p.importId});$('json-progress').textContent=`${r.processed} de ${r.total} processados. Pode haver resultados parciais se a conexão cair.`;}while(!r.done);p.results=Object.fromEntries(r.results.map(x=>[x.index,x]));p.status='complete';paintImport(r);toast('Importação concluída. Atualize a lista para consultar as matrículas.');}finally{importBusy=false;if(button)button.disabled=false;}});}

let profile=null,adminView=false,catalog={institutions:[],campuses:[],subjects:[]},myEnrollments=[],selectedSubjectId='',adminRows=[],adminCursor=null,studentRows=[],studentCursor=null;
const campusName=id=>catalog.campuses.find(x=>x.id===id)?.name||'Campus não definido';
const institutionName=id=>catalog.institutions.find(x=>x.id===id)?.name||'Instituição não definida';
const allowedSubjects=()=>catalog.subjects.filter(s=>adminView||(profile?.subjectIds||[]).includes(s.id)&&s.campusId===profile?.campusId&&s.institutionId===profile?.institutionId);
async function loadContext(){stopLive();const [p,c]=await Promise.all([call('getProfile'),call('getCatalog')]);profile=p.profile;adminView=p.isAdmin;catalog=c;const planCatalog=await call('getPlans');catalog.plans=planCatalog.plans||[];myEnrollments=p.enrollments||[];teacherView=profile?.role==='teacher'&&profile.status==='active';myModuleFeatures=teacherView?normalizePlan(catalog.plans.find(p=>p.id===(profile.planId||'free'))||DEFAULT_PLANS[0]).features:null;applyBrand(catalog.institutions.find(x=>x.id===profile?.institutionId)?.branding||null);header();if(adminView)return adminPanel();if(!profile||profile.status!=='active')return registration();if(teacherView){const billing=await call('getBilling');if(!billing.active)return billingPanel();return examList();}if(profile?.role==='staff')return academicHub();studentHome();}
function profileBanner(){return profile?`<p class="muted">${esc(profile.name)} · ${esc(institutionName(profile.institutionId))} · ${esc(campusName(profile.campusId))}</p>`:'';}
function registration(){const p=profile||{};app.innerHTML=`<div style="max-width:800px;margin:auto"><span class="eyebrow">Cadastro de acesso</span><h1>Seu vínculo com a aprendizagem.</h1>${p.status?`<div class="notice ${p.status==='rejected'||p.status==='suspended'?'warning':''}">Situação: <strong>${{pending:'Aguardando aprovação do administrador',rejected:'Cadastro não aprovado',suspended:'Acesso suspenso'}[p.status]||esc(p.status)}</strong>. ${p.status==='suspended'?'Entre em contato com o administrador.':'Você pode conferir ou reenviar seus dados abaixo.'}</div>`:''}<div class="card"><label for="register-name">Nome completo</label><input id="register-name" maxlength="120" value="${esc(p.name||user.displayName||'')}"><label for="register-role">Perfil solicitado</label><select id="register-role"><option value="student" ${p.role==='student'?'selected':''}>Estudante</option><option value="teacher" ${p.role==='teacher'?'selected':''}>Professor</option><option value="staff" ${p.role==='staff'?'selected':''}>Equipe de acompanhamento</option></select>${scopeSelects('register',p)}<div id="register-subjects"></div><div id="register-plan"></div><p class="muted">Instituição, campus e disciplinas do professor serão validados pelo administrador. Alunos podem ser matriculados em várias disciplinas após a aprovação do cadastro.</p><div class="actions"><button id="register-submit" ${p.status==='suspended'?'disabled':''}>Enviar cadastro para aprovação</button><button id="profile-refresh" class="outline">Verificar aprovação</button></div></div></div>`;bindScope('register',p,()=>paintRequested());$('register-role').onchange=paintRequested;paintRequested();on('profile-refresh',loadContext);on('register-submit',async()=>{await call('registerProfile',{name:$('register-name').value,role:$('register-role').value,institutionId:$('register-institution').value,campusId:$('register-campus').value,requestedPlanId:$('requested-plan')?.value||'free',requestedSubjectIds:[...document.querySelectorAll('[data-requested]:checked')].map(x=>x.dataset.requested)});toast('Solicitação enviada ao administrador.');await loadContext();});}
function scopeSelects(prefix,p={}){return `<div class="grid"><div><label for="${prefix}-institution">Instituição</label><select id="${prefix}-institution">${catalog.institutions.map(x=>`<option value="${esc(x.id)}" ${x.id===p.institutionId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div><label for="${prefix}-campus">Campus</label><select id="${prefix}-campus"></select></div></div>`;}
function bindScope(prefix,p={},changed=()=>{}){const paint=()=>{const list=catalog.campuses.filter(c=>c.institutionId===$(prefix+'-institution').value);$(prefix+'-campus').innerHTML=list.map(c=>`<option value="${esc(c.id)}" ${c.id===p.campusId?'selected':''}>${esc(c.name)}</option>`).join('');changed();};$(prefix+'-institution').onchange=paint;$(prefix+'-campus').onchange=changed;paint();}
function paintRequested(){if(!$('register-subjects'))return;if($('register-plan'))$('register-plan').innerHTML=$('register-role').value==='teacher'?`<label for="requested-plan">Plano desejado (sujeito à liberação do administrador)</label><select id="requested-plan">${planOptions(profile?.requestedPlanId||'free')}</select><p class="muted">O cadastro inicia no Free. Escolher Premium ou outro plano é uma solicitação, sem cobrança automática.</p>`:'';const p=profile||{};$('register-subjects').innerHTML=$('register-role').value==='teacher'?`<h3>Disciplinas solicitadas</h3>${catalog.subjects.filter(s=>s.campusId===$('register-campus').value).map(s=>`<label class="check"><input type="checkbox" data-requested="${esc(s.id)}" ${(p.requestedSubjectIds||[]).includes(s.id)?'checked':''}>${esc(s.name)}</label>`).join('')||'<p>Nenhuma disciplina cadastrada neste campus.</p>'}`:'';}
async function adminPanel(append=false){exam=null;const r=await call('adminUsers',append?{after:adminCursor}:{});adminRows=append?[...adminRows,...r.users]:r.users;adminCursor=r.next;app.innerHTML=`<span class="eyebrow">Administração de acesso</span><h1>Vínculos verificados.<br>Acessos definidos.</h1><div class="actions"><button id="admin-refresh" class="secondary">Atualizar cadastros</button><button id="admin-exams" class="outline">Consultar avaliações por disciplina</button><button id="admin-year" class="outline">Fechamento anual</button><button id="admin-leads" class="outline">Cadastros da demonstração</button><button id="admin-backup" class="outline">Backup e restauração</button><button id="admin-brand" class="outline">Identidade institucional</button><button id="admin-plans" class="outline">Planos e preços</button><button id="admin-students" class="outline">Matrículas por disciplina</button></div><details class="card"><summary>Cadastrar instituição, campus ou disciplina</summary><label for="catalog-type">O que cadastrar</label><select id="catalog-type"><option value="institutions">Instituição</option><option value="campuses">Campus</option><option value="subjects">Disciplina</option></select><label for="catalog-name">Nome</label><input id="catalog-name" maxlength="120">${scopeSelects('catalog')}<p class="muted">Para campus, escolha a instituição. Para disciplina, escolha instituição e campus. Ao criar instituição, os vínculos abaixo são ignorados.</p><button id="catalog-save">Cadastrar</button></details><div class="card"><h2>Professores e estudantes</h2><label for="admin-filter">Buscar nome, e-mail, campus ou situação</label><input id="admin-filter" placeholder="Ex.: pending, professor, campus…">${bulkControls()}<div id="admin-users"></div>${adminCursor?'<button id="admin-more" class="secondary">Carregar mais 100</button>':''}<p class="muted">A consulta considera os cadastros carregados. Aprovação e suspensão são registradas no histórico administrativo.</p></div>`;bindScope('catalog');bindBulk();paintAdminUsers();$('admin-filter').oninput=()=>{bulkSelected.clear();paintAdminUsers();};on('admin-year',()=>yearClosurePanel());on('admin-leads',()=>demoLeadsPanel());on('admin-backup',()=>backupPanel());on('admin-brand',()=>brandEditor());on('admin-plans',()=>plansPanel());on('admin-refresh',loadContext);on('admin-more',()=>adminPanel(true));on('admin-exams',()=>examList());on('admin-students',()=>studentsPanel());on('catalog-save',async()=>{await call('adminCatalog',{type:$('catalog-type').value,name:$('catalog-name').value,institutionId:$('catalog-institution').value,campusId:$('catalog-campus').value});toast('Cadastro criado.');catalog=await call('getCatalog');await adminPanel();});}
function paintAdminUsers(){const eligible=new Set(eligibleVisibleStudents().map(p=>p.uid));for(const uid of bulkSelected)if(!eligible.has(uid))bulkSelected.delete(uid);if($('bulk-count'))$('bulk-count').textContent=bulkSelected.size;const f=$('admin-filter').value.toLowerCase();$('admin-users').innerHTML=adminRows.filter(p=>(!$('bulk-campus')?.value||(p.campusId===$('bulk-campus').value&&p.institutionId===$('bulk-institution').value))).filter(p=>(p.name+' '+p.email+' '+p.role+' '+p.status+' '+campusName(p.campusId)).toLowerCase().includes(f)).map(p=>`<div class="profile-row"><div>${eligible.has(p.uid)?`<label class="check"><input type="checkbox" data-bulk-uid="${esc(p.uid)}" ${bulkSelected.has(p.uid)?'checked':''}><strong>${esc(p.name)}</strong></label>`:`<strong>${esc(p.name)}</strong>`} <span class="pill ${p.status==='active'?'':'bad'}">${esc(p.status)}</span><p class="muted">${({teacher:'Professor',student:'Estudante',staff:'Equipe de acompanhamento'}[p.role]||p.role)} · ${esc(p.email)}<br>${esc(institutionName(p.institutionId))} · ${esc(campusName(p.campusId))}</p></div><button class="outline" data-approve="${esc(p.uid)}">Revisar acesso</button></div>`).join('')||'<p>Nenhum cadastro encontrado.</p>';for(const box of document.querySelectorAll('[data-bulk-uid]'))box.onchange=()=>{if(box.checked)bulkSelected.add(box.dataset.bulkUid);else bulkSelected.delete(box.dataset.bulkUid);$('bulk-count').textContent=bulkSelected.size;};for(const b of document.querySelectorAll('[data-approve]'))b.onclick=guard(()=>approvalForm(b.dataset.approve));}
function approvalForm(uid){const p=adminRows.find(x=>x.uid===uid);app.innerHTML=`<button id="admin-back" class="outline">Voltar à administração</button><h1 style="font-size:40px">${esc(p.name)}</h1><p>${esc(p.email)} · ${({teacher:'Professor',student:'Estudante',staff:'Equipe de acompanhamento'}[p.role]||p.role)}</p><div class="card">${scopeSelects('approval',p)}<div id="approval-subjects"></div>${p.role==='teacher'?`<p>Plano solicitado: ${esc(p.requestedPlanId||'free')}</p><label for="approval-plan">Plano liberado pelo administrador</label><select id="approval-plan">${planOptions(p.planId||'free')}</select>`:''}<label for="approval-status">Decisão de acesso</label><select id="approval-status"><option value="active">Aprovar / manter ativo</option><option value="rejected">Não aprovar</option><option value="suspended">Suspender acesso</option></select><p class="muted">O professor acessa apenas o campus e as disciplinas atribuídas aqui. O aluno precisa também de matrícula em cada disciplina e turma. Alterar o campus não transfere matrículas automaticamente.</p><button id="approve-save">Salvar decisão</button>${p.role==='teacher'?'<button id="teacher-seats" class="outline">Revisar vagas de alunos</button><button id="teacher-revenue" class="outline">Percentuais e pagamentos</button>':''}</div>`;const paint=()=>{$('approval-subjects').innerHTML=p.role==='teacher'?`<h3>Disciplinas autorizadas</h3>${catalog.subjects.filter(s=>s.campusId===$('approval-campus').value).map(s=>`<label class="check"><input type="checkbox" data-assigned="${esc(s.id)}" ${(p.subjectIds?.length?p.subjectIds:p.requestedSubjectIds||[]).includes(s.id)?'checked':''}>${esc(s.name)}</label>`).join('')}`:'';};bindScope('approval',p,paint);if(['active','rejected','suspended'].includes(p.status))$('approval-status').value=p.status;on('admin-back',()=>adminPanel());on('teacher-seats',()=>teacherSeats(p.uid));on('teacher-revenue',()=>revenueSettingsForm(p));on('approve-save',async()=>{await call('approveProfile',{uid,institutionId:$('approval-institution').value,campusId:$('approval-campus').value,status:$('approval-status').value,subjectIds:[...document.querySelectorAll('[data-assigned]:checked')].map(x=>x.dataset.assigned)});if(p.role==='teacher')await call('assignTeacherPlan',{uid,planId:$('approval-plan').value});toast('Decisão registrada.');await adminPanel();});}
function subjectOptions(selected=selectedSubjectId){return allowedSubjects().map(s=>`<option value="${esc(s.id)}" ${s.id===selected?'selected':''}>${esc(s.name)} · ${esc(campusName(s.campusId))}</option>`).join('');}
async function studentsPanel(append=false){exam=null;const subjects=allowedSubjects();if(!subjects.length){toast('Nenhuma disciplina atribuída. Solicite o vínculo ao administrador.');return;}if(!subjects.some(s=>s.id===selectedSubjectId))selectedSubjectId=subjects[0].id;const r=await call('listStudents',{subjectId:selectedSubjectId,...append?{after:studentCursor}:{}});studentRows=append?[...studentRows,...r.students]:r.students;studentCursor=r.next;app.innerHTML=`<button id="students-back" class="outline">${adminView?'Administração':'Voltar às avaliações'}</button><h1 style="font-size:42px">Alunos e matrículas.</h1>${profileBanner()}<div class="card"><label for="student-subject">Disciplina</label><select id="student-subject">${subjectOptions()}</select><div class="actions"><button id="students-refresh" class="outline">Atualizar lista</button></div>${importControls()}<p class="muted">Somente estudantes com cadastro aprovado no mesmo campus podem ser matriculados. Cada estudante pode participar de várias disciplinas, com uma turma por disciplina.</p><label for="enroll-email">E-mail Google do aluno</label><input id="enroll-email" type="email"><label for="enroll-group">Turma nesta disciplina</label><input id="enroll-group" maxlength="80"><label class="check"><input id="enroll-active" type="checkbox" checked>Matrícula ativa</label><button id="enroll-save">Salvar matrícula</button><div class="question-table"><table><thead><tr><th>Aluno</th><th>E-mail</th><th>Turma</th><th>Matrícula</th><th>Ação</th></tr></thead><tbody>${studentRows.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.email)}</td><td>${esc(p.group)}</td><td>${p.active?'Ativa':'Inativa'}</td><td><button data-enrollment="${esc(p.uid)}" class="outline">Editar</button></td></tr>`).join('')||'<tr><td colspan="5">Nenhuma matrícula.</td></tr>'}</tbody></table></div>${studentCursor?'<button id="students-more" class="secondary">Carregar mais 100</button>':''}</div>`;bindImport();on('students-refresh',()=>studentsPanel());$('student-subject').onchange=()=>{selectedSubjectId=$('student-subject').value;guard(()=>studentsPanel())();};on('students-back',()=>adminView?adminPanel():examList());on('students-more',()=>studentsPanel(true));on('enroll-save',async()=>{await call('enrollStudent',{subjectId:selectedSubjectId,email:$('enroll-email').value,group:$('enroll-group').value,active:$('enroll-active').checked});toast('Matrícula atualizada.');await studentsPanel();});for(const b of document.querySelectorAll('[data-enrollment]'))b.onclick=()=>{const p=studentRows.find(x=>x.uid===b.dataset.enrollment);$('enroll-email').value=p.email;$('enroll-group').value=p.group;$('enroll-active').checked=p.active;};}

async function signedIn(u){user=u;header();if(!u){landing();await publicRoute();return;}await loadContext();await publicRoute();}
function meta(e){return `${esc(e.subject)} · ${esc(e.group)} · ${day(e.date)}`;}
async function examList(append=false){stopLive();active=false;exam=null;header();const subjects=allowedSubjects();if(!subjects.length){app.innerHTML='<div class="notice">Nenhuma disciplina atribuída. Solicite o vínculo ao administrador.</div>';return;}if(!subjects.some(s=>s.id===selectedSubjectId))selectedSubjectId=subjects[0].id;const r=await call('listExams',{subjectId:selectedSubjectId,...append?{after:examCursor}:{}});examRows=append?[...examRows,...r.exams]:r.exams;examCursor=r.next;app.innerHTML=`<span class="eyebrow">Espaço do professor</span><h1>Avaliações do seu campus.</h1>${profileBanner()}<div id="my-plan-card"></div><label for="scope-subject">Sua disciplina</label><select id="scope-subject">${subjectOptions()}</select><div class="actions"><button id="new-exam">Criar avaliação</button><button class="outline" id="reload">Atualizar</button><button class="secondary" id="student-preview">Acessar por código</button><button class="outline" id="students-nav">Alunos e matrículas</button>${adminView?'<button class="outline" id="admin-nav">Administração</button>':''}</div><label for="search">Buscar título, disciplina ou turma</label><input id="search" placeholder="Ex.: Matemática, INFO2…"><div id="exam-list" style="margin-top:24px"></div>${examCursor?'<button id="more-exams" class="secondary">Carregar mais 100</button>':''}`;$('scope-subject').onchange=()=>{selectedSubjectId=$('scope-subject').value;guard(()=>examList())();};on('students-nav',()=>studentsPanel());on('admin-nav',()=>adminPanel());paintExams();$('search').oninput=paintExams;on('new-exam',()=>editor());on('reload',()=>examList());on('more-exams',()=>examList(true));on('student-preview',studentHome);if(teacherView&&!adminView){const data=await call('getMyPlan');if($('my-plan-card'))$('my-plan-card').innerHTML=planSummary(data.plan,data.usage);}}
function paintExams(){const filter=$('search').value.toLowerCase();$('exam-list').innerHTML=examRows.filter(e=>(e.title+e.subject+e.group).toLowerCase().includes(filter)).map(e=>`<div class="card"><span class="pill ${e.open&&e.published?'':'bad'}">${!e.published?'Rascunho':e.open?'Publicada · aberta':'Publicada · fechada'}</span><h2>${esc(e.title)}</h2><p>${meta(e)}</p><p class="muted">${e.questionCount??e.questions?.length} questões · ${e.attemptCount||0} tentativas</p><div class="actions"><button data-dashboard="${esc(e.id)}">Respostas e correção</button><button class="outline" data-edit="${esc(e.id)}">Editar</button><button class="secondary" data-duplicate="${esc(e.id)}">Duplicar</button></div><p class="muted">Código: <strong>${esc(e.id)}</strong></p></div>`).join('')||'<div class="card">Nenhuma avaliação encontrada. Crie a primeira.</div>';for(const b of document.querySelectorAll('[data-dashboard]'))b.onclick=guard(()=>dashboard(b.dataset.dashboard));for(const b of document.querySelectorAll('[data-edit]'))b.onclick=guard(async()=>editor(await call('getExam',{examId:b.dataset.edit,teacher:true})));for(const b of document.querySelectorAll('[data-duplicate]'))b.onclick=guard(async()=>{const x=await call('getExam',{examId:b.dataset.duplicate,teacher:true});editor({...x,id:null,title:x.title+' — cópia',date:today(),open:false,published:false,attemptCount:0,revision:0});});}
function blankQuestion(type='choice'){return{id:uuid(),type,prompt:type==='blanks'?'Complete: {{1}} é uma palavra e {{2}} é outra.':'',points:1,rubric:'',code:'',language:'',...(type==='choice'?{options:['',''],correct:0}:type==='multiple'?{options:['',''],corrects:[0,1]}:type==='blanks'?{blanks:[{accepted:[]},{accepted:[]}],ignoreCase:true,ignoreAccents:false}:{responseFormat:'text'})};}
function editor(e=null){editing=structuredClone(e||{title:'',subject:'',date:today(),group:'',instructions:'Responda individualmente. Leia as questões com atenção e explique com suas palavras.',published:false,open:false,thresholds:{B:75,C:50},questions:[blankQuestion()],revision:0});editing.mode=editing.mode||'assessment';editing.presentation=editing.presentation||{value:'count',chart:'bars'};editing.grading=gradingConfig(editing);editing.subjectId=editing.subjectId||selectedSubjectId;const chosen=allowedSubjects().find(x=>x.id===editing.subjectId);if(chosen){editing.subject=chosen.name;editing.campusId=chosen.campusId;editing.institutionId=chosen.institutionId;}drawEditor();}
function drawEditor(){const e=editing,locked=e.attemptCount>0;app.innerHTML=`<button id="cancel-edit" class="outline">Voltar às avaliações</button><span class="eyebrow" style="display:block;margin-top:24px">${e.id?'Editar avaliação':'Nova avaliação'}</span><h1 style="font-size:42px">Planejar a aprendizagem.</h1>${locked?'<div class="notice">Já existem tentativas: conteúdo, disciplina, turma e data estão preservados. Você pode abrir ou fechar a avaliação e ajustar os limites dos conceitos. O tipo de resultado e a escala ficam preservados. Para mudar o conteúdo, use Duplicar.</div>':''}<div class="card"><h2>Identificação</h2><label for="activity-mode">Tipo de atividade</label><select id="activity-mode" ${locked?'disabled':''}><option value="assessment" ${e.mode==='assessment'?'selected':''}>Avaliação individual</option><option value="live" ${e.mode==='live'?'selected':''}>Quiz ao vivo (formativo)</option></select><div ${e.mode==='live'?'':'hidden'}><p class="notice">O professor controla uma pergunta por vez e acompanha a distribuição em tempo real. O quiz ao vivo é formativo: não gera conceito/nota automaticamente. Use questões de escolha única, múltiplas respostas ou texto curto (até 200 caracteres). Lacunas e respostas em código ficam na avaliação individual.</p><div class="grid"><div><label for="live-value">Exibir resultados como</label><select id="live-value"><option value="count" ${e.presentation.value==='count'?'selected':''}>Numérico (contagem)</option><option value="percent" ${e.presentation.value==='percent'?'selected':''}>Porcentagem</option></select></div><div><label for="live-chart">Gráfico padrão</label><select id="live-chart">${chartOptions(e.presentation.chart)}</select></div></div></div><label for="title">Título da avaliação</label><input id="title" maxlength="150" value="${esc(e.title)}" ${locked?'disabled':''}><div class="grid"><div><label for="subject">Disciplina</label><select id="subject" ${locked?'disabled':''}>${subjectOptions(e.subjectId)}</select></div><div><label for="exam-date">Dia da aplicação</label><input type="date" id="exam-date" value="${esc(e.date)}" ${locked?'disabled':''}></div><div><label for="group">Turma</label><input id="group" maxlength="80" value="${esc(e.group)}" ${locked?'disabled':''}></div></div><label for="exam-course">Vincular a um curso (código opcional)</label><input id="exam-course" value="${esc(e.courseId||'')}" ${locked?'disabled':''} placeholder="Código do curso de sua autoria"><p class="muted">A turma será a do curso. A matrícula e a validade do curso liberam esta atividade.</p><label for="instructions">Orientações aos estudantes</label><textarea id="instructions" maxlength="4000" style="min-height:100px" ${locked?'disabled':''}>${esc(e.instructions)}</textarea></div><div class="card"><h2>Questões</h2><p class="muted">De 1 a 60 questões. Objetivas: de 2 a 6 alternativas, uma correta. Abertas: correção docente com critérios privados. Lacunas: gabarito por campo e crédito parcial automático. O peso de cada questão compõe o aproveitamento final.</p><div id="question-editor"></div>${!locked?'<div class="actions"><button class="secondary" id="add-choice">Adicionar objetiva</button><button class="outline" id="add-multiple">Adicionar múltiplas respostas</button><button class="outline" id="add-open">Adicionar aberta</button><button class="outline" id="add-blanks">Adicionar lacunas</button></div>':''}</div><div class="card"><h2>Forma de avaliação e publicação</h2><label for="grading-mode">Avaliar por</label><select id="grading-mode" ${locked?'disabled':''}><option value="concept" ${e.grading.mode==='concept'?'selected':''}>Conceito (A, B, C ou D)</option><option value="numeric" ${e.grading.mode==='numeric'?'selected':''}>Nota numérica</option></select><div ${e.grading.mode==='numeric'?'':'hidden'}><div class="grid"><div><label for="grade-max">Nota máxima</label><input id="grade-max" type="number" min="1" max="1000" step="any" value="${e.grading.max}" ${locked?'disabled':''}></div><div><label for="grade-decimals">Casas decimais da nota</label><select id="grade-decimals" ${locked?'disabled':''}>${[0,1,2,3].map(n=>`<option value="${n}" ${e.grading.decimals===n?'selected':''}>${n}</option>`).join('')}</select></div></div><p class="muted">Nota de zero até o máximo escolhido (por exemplo, 10 ou 100), proporcional aos pesos das questões após os descontos. Arredondamento aplicado apenas ao resultado final.</p></div><div ${e.grading.mode==='concept'?'':'hidden'}><p>A = 100% do aproveitamento final. B = poucos erros. C = precisa melhorar. D = recuperação.</p><div class="grid"><div><label for="threshold-b">Mínimo para B (%)</label><input type="number" min="1" max="99" id="threshold-b" value="${e.thresholds.B}"></div><div><label for="threshold-c">Mínimo para C (%)</label><input type="number" min="1" max="98" id="threshold-c" value="${e.thresholds.C}"></div></div></div><label class="check"><input type="checkbox" id="published" ${e.published?'checked':''} ${locked?'disabled':''}> Publicar avaliação para acesso pelo código</label><label class="check"><input type="checkbox" id="isopen" ${e.open?'checked':''}> Aberta para iniciar e retomar</label><p class="muted">Novas tentativas e retomadas só são permitidas no dia escolhido (horário de Brasília), com a avaliação publicada e aberta. Sessões já iniciadas podem salvar e entregar após o fechamento. Revisões anteriores preservam os critérios utilizados.</p><button id="save-exam">Salvar avaliação</button><p id="editor-status" class="muted">O cadastro só é gravado ao clicar em Salvar avaliação.</p></div>`;paintQuestionEditor();addBankControls();on('grading-mode',()=>{});$('grading-mode').onchange=()=>{captureEditor();drawEditor();};on('cancel-edit',()=>examList());on('add-choice',()=>{captureEditor();if(e.questions.length>=60)throw Error('Limite de 60 questões.');e.questions.push(blankQuestion());drawEditor();});on('add-open',()=>{captureEditor();if(e.questions.length>=60)throw Error('Limite de 60 questões.');e.questions.push(blankQuestion('open'));drawEditor();});$('activity-mode').onchange=()=>{captureEditor();drawEditor();};on('add-multiple',()=>{captureEditor();if(e.questions.length>=60)throw Error('Limite de 60 questões.');e.questions.push(blankQuestion('multiple'));drawEditor();});on('add-blanks',()=>{captureEditor();if(e.questions.length>=60)throw Error('Limite de 60 questões.');e.questions.push(blankQuestion('blanks'));drawEditor();});on('save-exam',async()=>{captureEditor();validateEditor(e);const payload=cleanExam(e);const r=await call('saveExam',{examId:e.id||null,exam:payload,expectedRevision:e.revision});toast('Avaliação salva.');await dashboard(r.id);});}
function paintQuestionEditor(){const locked=editing.attemptCount>0;$('question-editor').innerHTML=editing.questions.map((q,i)=>`<section class="question-edit" data-editor-index="${i}"><div class="actions"><h3 style="margin-right:auto">Questão ${i+1} · ${q.type==='choice'?'Objetiva':q.type==='multiple'?'Múltiplas respostas':q.type==='blanks'?'Lacunas':'Aberta'}</h3>${!locked?`<button class="outline" data-up="${i}" ${i===0?'disabled':''}>Subir</button><button class="outline" data-down="${i}" ${i===editing.questions.length-1?'disabled':''}>Descer</button><button class="outline" data-remove="${i}">Remover</button>`:''}</div><label for="prompt-${i}">Enunciado</label><textarea id="prompt-${i}" maxlength="10000" ${locked?'disabled':''}>${esc(q.prompt)}</textarea>${q.type==='blanks'?`<p class="muted">Use {{1}}, {{2}}, … em ordem, uma vez cada, até 20 lacunas. Cada lacuna vale uma fração igual do peso da questão.</p><div class="actions"><button class="secondary" data-refresh-blanks="${i}" ${locked?'disabled':''}>Atualizar lacunas do enunciado</button></div>${(q.blanks||[]).map((b,j)=>`<label for="blank-key-${i}-${j}">Respostas aceitas para lacuna ${j+1} — uma por linha</label><textarea id="blank-key-${i}-${j}" maxlength="1100" style="min-height:85px" ${locked?'disabled':''}>${esc((b.accepted||[]).join('\n'))}</textarea>`).join('')}<label class="check"><input id="ignore-case-${i}" type="checkbox" ${q.ignoreCase?'checked':''} ${locked?'disabled':''}>Ignorar maiúsculas e minúsculas</label><label class="check"><input id="ignore-accents-${i}" type="checkbox" ${q.ignoreAccents?'checked':''} ${locked?'disabled':''}>Ignorar acentos</label>`:''}<label for="code-${i}">Código-fonte no enunciado (opcional)</label><textarea id="code-${i}" class="code-editor" maxlength="20000" spellcheck="false" wrap="off" ${locked?'disabled':''}>${esc(q.code||'')}</textarea><label for="language-${i}">Linguagem do código (rótulo opcional)</label><input id="language-${i}" maxlength="40" value="${esc(q.language||'')}" placeholder="Ex.: Python, JavaScript, C" ${locked?'disabled':''}>${q.type==='open'?`<label for="response-format-${i}">Tipo de resposta aberta</label><select id="response-format-${i}" ${locked?'disabled':''}><option value="text" ${(q.responseFormat||'text')==='text'?'selected':''}>Texto</option><option value="code" ${q.responseFormat==='code'?'selected':''}>Código</option></select>`:''}<label for="points-${i}">Peso (pontos)</label><input id="points-${i}" type="number" min="0.01" max="100" step="0.01" value="${q.points}" ${locked?'disabled':''}>${['choice','multiple'].includes(q.type)?`<div class="alternatives-editor">${q.options.map((o,j)=>`<label for="option-${i}-${j}">Alternativa ${'ABCDEF'[j]}</label><input id="option-${i}-${j}" maxlength="2000" value="${esc(o)}" ${locked?'disabled':''}>`).join('')}</div>${q.type==='multiple'?`<h4>Alternativas corretas (marque pelo menos duas)</h4>${q.options.map((o,j)=>`<label class="check"><input type="checkbox" data-correct-multiple="${i}-${j}" ${(q.corrects||[]).includes(j)?'checked':''} ${locked?'disabled':''}>Alternativa ${'ABCDEF'[j]}</label>`).join('')}<p class="muted">Pontuação = peso − (corretas não marcadas + erradas marcadas) × peso/número de corretas, com mínimo zero. Marcar tudo não garante acerto integral.</p>`:`<label for="correct-${i}">Alternativa correta — somente professor</label><select id="correct-${i}" ${locked?'disabled':''}>${q.options.map((o,j)=>`<option value="${j}" ${q.correct===j?'selected':''}>${'ABCDEF'[j]}</option>`).join('')}</select>`}${!locked?`<div class="actions"><button class="secondary" data-add-option="${i}">Adicionar alternativa</button><button class="outline" data-remove-option="${i}">Remover última alternativa</button></div>`:''}`:''}${editing.mode==='live'?`<label for="question-chart-${i}">Gráfico desta pergunta</label><select id="question-chart-${i}" ${locked?'disabled':''}><option value="inherit">Usar gráfico padrão</option>${chartOptions(q.presentationChart||'inherit')}</select>`:''}<label for="rubric-${i}">${q.type==='open'?'Resposta esperada e critérios de correção':'Comentário do gabarito'} — privado</label><textarea id="rubric-${i}" maxlength="6000" style="min-height:100px" ${locked?'disabled':''}>${esc(q.rubric)}</textarea></section>`).join('');for(const b of document.querySelectorAll('[data-refresh-blanks]'))b.onclick=guard(()=>{captureEditor();const i=Number(b.dataset.refreshBlanks),q=editing.questions[i],ids=blankIds(q.prompt);if(!ids.length||ids.length>20||ids.some((n,j)=>n!==j+1))throw Error('Use marcadores {{1}}, {{2}}, … em sequência, sem repetir.');q.blanks=ids.map((_,j)=>q.blanks[j]||{accepted:[]});drawEditor();});for(const el of document.querySelectorAll('.code-editor'))bindCodeEditor(el);for(const b of document.querySelectorAll('[data-remove]'))b.onclick=guard(()=>{captureEditor();if(editing.questions.length===1)throw Error('Mantenha pelo menos uma questão.');editing.questions.splice(Number(b.dataset.remove),1);drawEditor();});for(const attr of ['up','down','add-option','remove-option'])for(const b of document.querySelectorAll(`[data-${attr}]`))b.onclick=guard(()=>{captureEditor();const i=Number(b.getAttribute('data-'+attr)),q=editing.questions[i];if(attr==='up'||attr==='down'){const j=i+(attr==='up'?-1:1);[editing.questions[i],editing.questions[j]]=[editing.questions[j],editing.questions[i]];}else if(attr==='add-option'){if(q.options.length>=6)throw Error('Máximo de seis alternativas.');q.options.push('');}else{if(q.options.length<=2)throw Error('Mantenha pelo menos duas alternativas.');q.options.pop();if(q.type==='multiple')q.corrects=q.corrects.filter(n=>n<q.options.length);else q.correct=Math.min(q.correct,q.options.length-1);}drawEditor();});}
function captureEditor(){const e=editing;e.title=$('title').value.trim();e.subjectId=$('subject').value;const scopedSubject=allowedSubjects().find(s=>s.id===e.subjectId);if(scopedSubject){e.subject=scopedSubject.name;e.institutionId=scopedSubject.institutionId;e.campusId=scopedSubject.campusId;}e.courseId=$('exam-course').value.trim();e.group=$('group').value.trim();e.date=$('exam-date').value;e.instructions=$('instructions').value;e.mode=$('activity-mode').value;e.presentation={value:$('live-value').value,chart:$('live-chart').value};e.published=$('published').checked;e.open=$('isopen').checked;e.thresholds={B:Number($('threshold-b').value),C:Number($('threshold-c').value)};e.grading={mode:$('grading-mode').value,max:Number($('grade-max').value),decimals:Number($('grade-decimals').value)};e.questions.forEach((q,i)=>{q.prompt=$('prompt-'+i).value;q.points=Number($('points-'+i).value);q.rubric=$('rubric-'+i).value;if($('bank-topic-'+i)&&!(editing.attemptCount>0))q.topic=$('bank-topic-'+i).value.trim();if($('question-chart-'+i)&&!(editing.attemptCount>0))q.presentationChart=$('question-chart-'+i).value;if(!(editing.attemptCount>0)){q.code=$('code-'+i).value;q.language=$('language-'+i).value;if(q.type==='open')q.responseFormat=$('response-format-'+i).value;if(q.type==='blanks'){q.blanks=q.blanks.map((b,j)=>({accepted:$('blank-key-'+i+'-'+j).value.split('\n').map(x=>x.trim()).filter(Boolean)}));q.ignoreCase=$('ignore-case-'+i).checked;q.ignoreAccents=$('ignore-accents-'+i).checked;}}if(['choice','multiple'].includes(q.type)){q.options=q.options.map((_,j)=>$('option-'+i+'-'+j).value);if(q.type==='multiple')q.corrects=q.options.map((_,j)=>j).filter(j=>document.querySelector(`[data-correct-multiple="${i}-${j}"]`).checked);else q.correct=Number($('correct-'+i).value);}});}
function cleanExam(e){return Object.fromEntries(['title','subject','group','date','instructions','published','open','thresholds','questions','grading','subjectId','institutionId','campusId','mode','presentation','courseId'].map(k=>[k,e[k]]));}
function validateEditor(e){if(!validateLiveConfig(e))throw Error('Confira o quiz: use escolha única, múltiplas respostas ou texto curto. Nuvem de palavras exige pergunta aberta em texto.');if(!e.title||!e.subject||!e.group||!e.date)throw Error('Preencha título, disciplina, turma e data.');if(!(0<e.thresholds.C&&e.thresholds.C<e.thresholds.B&&e.thresholds.B<100))throw Error('Use 0 < C < B < 100.');const g=gradingConfig(e);if(!Number.isFinite(g.max)||g.max<1||g.max>1000||!Number.isInteger(g.decimals)||g.decimals<0||g.decimals>3)throw Error('Confira a nota máxima (1 a 1000) e as casas decimais (0 a 3).');for(const [i,q]of e.questions.entries())if(!validateQuestionExtras(q)||!q.prompt.trim()||q.points<=0||q.points>100||!Number.isFinite(q.points)||(q.type==='choice'&&q.options.some(o=>!o.trim())))throw Error(`Complete o enunciado, as alternativas e o peso da questão ${i+1}.`);}
function studentHome(){stopLive();exam=null;active=false;document.body.classList.remove('active-exam');app.innerHTML=`<div style="max-width:700px;margin:auto"><span class="eyebrow">Espaço do estudante</span><h1>Encontre sua avaliação.</h1>${profileBanner()}${myEnrollments.length?`<div class="card"><h3>Minhas disciplinas</h3>${myEnrollments.map(e=>`<p>${esc(e.subject)} · ${esc(e.group)}</p>`).join('')}</div>`:''}<div class="card"><label for="exam-code">Código informado pelo professor</label><input id="exam-code" maxlength="128" autocomplete="off" value="${esc(new URLSearchParams(location.search).get('sessao')||new URLSearchParams(location.search).get('avaliacao')||'')}" placeholder="Cole ou digite o código"><div class="actions"><button id="find-exam">Acessar avaliação</button>${teacherView?'<button id="teacher-back" class="outline">Voltar ao painel docente</button>':''}</div>${demo?'<p class="muted">Código de demonstração: <strong>demo-avaliacao</strong></p>':''}</div></div>`;on('find-exam',async()=>{const entered=$('exam-code').value.trim();if(entered.startsWith('live-'))return joinLive(entered);exam=await call('getExam',{examId:$('exam-code').value.trim()});qs=exam.questions;await welcome();});on('teacher-back',()=>examList());}
async function welcome(){active=false;attempt=await call('getMyAttempt');if(attempt&&attempt.status!=='active'){receipt();return;}app.innerHTML=`<div style="max-width:750px;margin:auto"><button class="outline" id="student-back">Escolher outra avaliação</button><h1 style="font-size:42px">${esc(exam.title)}</h1><p>${meta(exam)}</p><div class="card"><span class="pill ${exam.available?'':'bad'}">${exam.available?'Aberta para respostas':'Fora do dia previsto ou fechada'}</span><p>${qs.length} questões · ${qs.filter(q=>['choice','multiple'].includes(q.type)).length} objetivas · ${qs.filter(q=>q.type==='open').length} abertas · ${qs.filter(q=>q.type==='blanks').length} com lacunas</p><p class="pre">${esc(exam.instructions)}</p><label for="name">Nome completo</label><input id="name" maxlength="120" value="${esc(attempt?.name||user.displayName||'')}"><p class="muted">Turma: ${esc(exam.group)}. Campus: ${esc(campusName(exam.campusId))}. O acesso exige matrícula ativa nesta disciplina e turma.</p><div class="notice">Permaneça na avaliação. Tentativas de copiar e colar são bloqueadas e eventos de saída podem ser registrados. Notificações também podem gerar ocorrências; avise o professor se houver um imprevisto. Capturas de tela não são verificáveis.</div><p class="muted">${gradingConfig(exam).mode==='numeric'?`Avaliação por nota: de 0 a ${gradingConfig(exam).max}, com ${gradingConfig(exam).decimals} casa(s) decimal(is).`:`Conceitos: A = 100%; B ≥ ${exam.thresholds.B}%; C ≥ ${exam.thresholds.C}%; D abaixo do mínimo de C.`} A correção e os ajustes justificados definem o resultado final.</p><label class="check"><input id="aware" type="checkbox">Li as orientações e estou ciente do registro de ocorrências.</label><button id="begin">${attempt?'Retomar avaliação':'Iniciar avaliação'}</button></div></div>`;on('student-back',studentHome);on('begin',async()=>{if(!$('aware').checked)throw Error('Confirme a leitura das orientações.');attempt=await call('startAttempt',{sessionId,name:$('name').value});if(attempt.status!=='active'){receipt();return;}answers={...attempt.answers};revision=attempt.revision||0;savedRevision=revision;pending=[];try{const p=JSON.parse(localStorage.getItem(localKey())||'null');if(p?.sessionId===sessionId){if(p.revision>revision){answers=p.answers;revision=p.revision;}pending=p.pending||[];}}catch{}active=true;document.body.classList.add('active-exam');qindex=0;record(attempt.revision?'resume':'started');renderQuestion();await flush();});}
const isAnswered=q=>q.type==='multiple'?Array.isArray(answers[q.id]):q.type==='blanks'?Array.isArray(answers[q.id])&&answers[q.id].length===q.blanks.length&&answers[q.id].every(v=>typeof v==='string'&&!!v.trim()):q.type==='choice'?Number.isInteger(answers[q.id]):!!answers[q.id]?.trim();const answered=()=>qs.filter(isAnswered).length;
function renderQuestion(){const q=qs[qindex];app.innerHTML=`<div class="exam-layout"><aside class="card exam-side"><span class="eyebrow">${esc(exam.subject)}</span><h3>${esc(exam.title)}</h3><p id="progress-text">${answered()} de ${qs.length} respondidas</p><div class="progress"><span id="progress-bar" style="width:${answered()/qs.length*100}%"></span></div><div class="numbers" style="margin-top:20px">${qs.map((x,i)=>`<button data-q="${i}" class="${isAnswered(x)?'answered':''} ${i===qindex?'current':''}" aria-label="Questão ${i+1}">${i+1}</button>`).join('')}</div><p id="sync" class="muted" role="status"></p></aside><section><div class="actions" style="margin-top:0"><span class="chip">${esc(exam.group)}</span><span class="muted">Questão ${qindex+1} de ${qs.length}</span><button id="fullscreen" class="outline" style="margin-left:auto">Tela cheia</button></div><div class="card question-content"><span class="eyebrow">${q.type==='choice'?'Objetiva':q.type==='multiple'?'Selecione todas as corretas':q.type==='blanks'?'Complete as lacunas':q.responseFormat==='code'?'Resposta em código':'Resposta aberta'}</span><div class="qtitle pre">${q.type==='blanks'?renderInlineBlanks(q,answers[q.id]||[]):esc(q.prompt)}</div>${renderCodeBlock(q)}${q.type==='multiple'?`${q.options.map((o,i)=>`<label class="option"><input type="checkbox" data-multiple="${i}" ${(answers[q.id]||[]).includes(i)?'checked':''}><b>${'ABCDEF'[i]}</b><span>${esc(o)}</span></label>`).join('')}<p class="notice">Há mais de uma correta. Cada correta não marcada e cada errada marcada descontam uma fração do peso; mínimo zero nesta questão.</p><button id="no-multiple" class="outline">Não sei / deixar sem alternativa</button>`:q.type==='choice'?q.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" ${answers[q.id]===i?'checked':''}><b>${'ABCDEF'[i]}</b><span>${esc(o)}</span></label>`).join(''):q.type==='blanks'?`<p class="muted">Preencha cada campo no texto. ${q.ignoreCase?'Maiúsculas e minúsculas não diferenciam respostas.':''} ${q.ignoreAccents?'Acentos não diferenciam respostas.':''}</p>`:`<label for="written">${q.responseFormat==='code'?'Seu código':'Sua resposta'}</label><textarea id="written" class="${q.responseFormat==='code'?'code-editor':''}" ${q.responseFormat==='code'?'spellcheck="false" autocapitalize="off" autocomplete="off" wrap="off"':''} maxlength="10000" placeholder="${q.responseFormat==='code'?'Digite o código com a indentação desejada…':'Responda com suas palavras…'}">${esc(answers[q.id]||'')}</textarea><small id="chars">${(answers[q.id]||'').length}/10000 caracteres</small>`}</div><div class="actions"><button class="outline" id="prev" ${qindex===0?'disabled':''}>Anterior</button>${qindex<qs.length-1?'<button id="next">Próxima questão</button>':'<button id="check">Revisar e entregar</button>'}</div></section></div>`;document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{qindex=Number(b.dataset.q);renderQuestion();});for(const el of document.querySelectorAll('[data-multiple]'))el.onchange=()=>changeAnswer(q.id,[...document.querySelectorAll('[data-multiple]:checked')].map(x=>Number(x.dataset.multiple)));on('no-multiple',()=>{changeAnswer(q.id,[]);renderQuestion();});document.querySelectorAll('[name=answer]').forEach(el=>el.onchange=()=>changeAnswer(q.id,Number(el.value)));for(const el of document.querySelectorAll('[data-blank]'))el.oninput=()=>{const values=Array.isArray(answers[q.id])?[...answers[q.id]]:Array(q.blanks.length).fill('');values[Number(el.dataset.blank)]=el.value;changeAnswer(q.id,values);};if($('written')&&q.responseFormat==='code')bindCodeEditor($('written'));if($('written'))$('written').oninput=()=>{changeAnswer(q.id,$('written').value);$('chars').textContent=`${$('written').value.length}/10000 caracteres`;};on('prev',()=>{qindex--;renderQuestion();});on('next',()=>{qindex++;renderQuestion();});on('check',confirmSubmit);on('fullscreen',async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();}catch{record('fullscreen_unavailable');toast('Tela cheia indisponível. Continue normalmente.');}});syncLabel();}
function persist(){if(active)localStorage.setItem(localKey(),JSON.stringify({sessionId,answers,revision,pending}));}
function changeAnswer(id,v){answers[id]=v;revision++;persist();$('progress-text').textContent=`${answered()} de ${qs.length} respondidas`;$('progress-bar').style.width=answered()/qs.length*100+'%';document.querySelector(`[data-q="${qindex}"]`)?.classList.toggle('answered',isAnswered(qs[qindex]));clearTimeout(saveTimer);saveTimer=setTimeout(()=>flush().catch(e=>toast(friendly(e))),750);syncLabel();}
function syncLabel(){if($('sync'))$('sync').textContent=!navigator.onLine?'Sem conexão · pendente':saving?'Salvando…':revision>savedRevision||pending.length?'Alterações pendentes':demo?'Salvo nesta demonstração':'Salvo no servidor';}
async function flush(){if(flushing){await flushing;return flush();}if(!active)return;if(!navigator.onLine&&!demo)throw Error('Sem conexão.');saving=true;syncLabel();flushing=(async()=>{const rev=revision;if(rev>savedRevision){await call('saveAnswers',{sessionId,answers:{...answers},revision:rev});savedRevision=rev;}while(pending.length){const batch=pending.slice(0,60),r=await call('logEvents',{sessionId,events:batch});pending=pending.filter(e=>!r.ids.includes(e.id));persist();}})();try{await flushing;}finally{saving=false;flushing=null;syncLabel();}}
function confirmSubmit(){if(answered()<qs.length){toast(`Faltam ${qs.length-answered()} questões.`);qindex=qs.findIndex(q=>!isAnswered(q));renderQuestion();return;}app.innerHTML=`<div class="card"><span class="eyebrow">Conferência final</span><h1 style="font-size:38px">Suas ${qs.length} respostas estão prontas.</h1><p>Depois de entregar, não será possível alterar as respostas.</p><div class="actions"><button id="return" class="outline">Voltar à avaliação</button><button id="submit">Confirmar entrega</button></div><p id="sync" class="muted"></p></div>`;on('return',renderQuestion);on('submit',async()=>{await flush();await call('submitAttempt',{sessionId,answers});active=false;localStorage.removeItem(localKey());document.body.classList.remove('active-exam');attempt=await call('getMyAttempt');receipt();});syncLabel();}
function receipt(){active=false;document.body.classList.remove('active-exam');const r=attempt?.review;app.innerHTML=`<div style="max-width:730px;margin:auto"><span class="eyebrow">${esc(exam.subject)}</span><h1>Entrega confirmada.</h1><div class="card"><h2>${esc(exam.title)}</h2><p>${esc(attempt.name)} · ${esc(attempt.group)} · ${date(attempt.submittedAt)}</p>${demo?'<p class="pill bad">Simulação local</p>':''}${r?.published?`<span class="eyebrow">${(r.grading||gradingConfig(exam)).mode==='numeric'?'Nota final':'Conceito final'}</span><div class="concept">${esc(resultText(r))}</div><p class="pre">${esc(r.feedback||'Revisão concluída.')}</p><h3>Devolutiva por questão</h3>${qs.map((q,i)=>{const qr=r.questionResults?.[q.id];const value=qr?`${qr.earned}/${qr.max} do peso · ${qr.percent.toLocaleString('pt-BR',{maximumFractionDigits:1})}% de acerto${qr.numericContribution!==null?` · contribuição ${qr.numericContribution.toLocaleString('pt-BR',{maximumFractionDigits:3})} na nota`:` · contribuição ${qr.weightedPercent.toLocaleString('pt-BR',{maximumFractionDigits:1})}% na avaliação`}`:q.type==='open'?`${r.manual?.[q.id]??0}/${q.points} ponto(s) do peso`:'Correção objetiva incluída no resultado';return `<div class="review-answer"><strong>Questão ${i+1}</strong><br>${esc(value)}${q.type==='open'?`<br>${esc(r.questionFeedback?.[q.id]||'Sem feedback individual registrado.')}`:''}</div>`;}).join('')}${r.deduction?`<p>Ajuste registrado: ${esc(r.reason)}</p>`:''}`:'<p>Aguarde a correção e a revisão do professor.</p>'}<div class="actions"><button class="secondary" id="refresh-result">Atualizar resultado</button><button class="outline" id="student-back">Outras avaliações</button></div></div></div>`;on('refresh-result',async()=>{attempt=await call('getMyAttempt');receipt();});on('student-back',studentHome);header();}

function record(type,duration=0){if(!active)return;pending.push({id:uuid(),type,clientAt:Date.now(),duration:Math.min(86400000,Math.max(0,duration)),question:qs[qindex]?.id||''});persist();syncLabel();flush().catch(()=>{});}
let hiddenAt=null,blurAt=null;
document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenAt=Date.now();record('hidden');}else{record('visible',hiddenAt?Date.now()-hiddenAt:0);hiddenAt=null;}});
