document.addEventListener('keydown',e=>{if(!active)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='p'){e.preventDefault();record('print_shortcut');}if(e.key==='PrintScreen')record('printscreen_key');});
