function paintRows(){const f=$('filter').value.toLowerCase();$('students').innerHTML=rows.filter(a=>a.name.toLowerCase().includes(f)).map(a=>`<tr><td>${esc(a.name)}</td><td>${{active:'Em andamento',submitted:'Entregue',reviewed:'Revisada'}[a.status]}</td><td>${esc(resultText(a.review))}${a.review&&!a.review.published?' · rascunho':''}</td><td><button data-student="${esc(a.uid)}" class="outline">Abrir</button></td></tr>`).join('')||'<tr><td colspan="4">Nenhuma tentativa.</td></tr>';for(const b of document.querySelectorAll('[data-student]'))b.onclick=guard(()=>detail(b.dataset.student));}
function localGrade(e,a,manual,deduction){let objective=0,max=0;for(const q of e.questions){max+=q.points;objective+=automaticPoints(q,a[q.id]);}const raw=objective+Object.values(manual).reduce((s,n)=>s+n,0),total=Math.max(0,Math.round((raw-deduction)*10000)/10000),percent=total/max*100;const grading=gradingConfig(e),numericGrade=grading.mode==='numeric'?Math.round(percent/100*grading.max*10**grading.decimals)/10**grading.decimals:null;const questionResults=Object.fromEntries(e.questions.map(q=>{const earned=q.type==='open'?(manual[q.id]||0):automaticPoints(q,a[q.id]);return[q.id,{earned,max:q.points,...(q.type==='blanks'?{blankResults:blankResults(q,a[q.id])}:{}),...(q.type==='multiple'?{penalties:multipleBreakdown(q,a[q.id])}:{}),percent:earned/q.points*100,weightedPercent:earned/max*100,numericContribution:grading.mode==='numeric'?earned/max*grading.max:null}];}));return{objective,raw,total,totalMax:max,percent,grading,numericGrade,questionResults,concept:grading.mode==='numeric'?null:percent>=100-1e-8?'A':percent>=e.thresholds.B?'B':percent>=e.thresholds.C?'C':'D'};}
async function detail(uid){const d=await call('teacherData',{uid});currentDetail=d;exam=d.exam;qs=exam.questions;const a=d.attempt,r=a.review||{},max=qs.reduce((s,q)=>s+q.points,0);app.innerHTML=`<button id="back" class="outline">Voltar à avaliação</button><h1 style="font-size:40px">${esc(a.name)}</h1><p>${meta(exam)} · ${esc(a.email)}</p><div class="notice warning">Ocorrências são relatos técnicos do navegador, não prova de consulta. Notificações podem gerar perda de foco. Capturas de tela não são verificáveis. Revise o contexto antes de descontar.</div>${a.status==='active'?'<div class="card"><h2>Tentativa em andamento</h2><p>A correção será liberada após a entrega.</p><button id="release" class="secondary">Liberar retomada em outra sessão</button></div>':''}<h2>Respostas e correção</h2>${qs.map((q,i)=>`<details class="card" ${q.type==='open'?'open':''}><summary>${i+1}. ${esc(q.prompt.slice(0,100))}</summary><p class="pre">${esc(q.prompt)}</p>${renderCodeBlock(q)}<div class="review-answer ${q.responseFormat==='code'?'code-review':''}">${esc(q.type==='choice'?(Number.isInteger(a.answers[q.id])?'ABCDEF'[a.answers[q.id]]+') '+q.options[a.answers[q.id]]:'Sem resposta'):q.type==='multiple'?(a.answers[q.id]||[]).map(n=>'ABCDEF'[n]+') '+q.options[n]).join('\n')||'Nenhuma alternativa marcada':q.type==='blanks'?(a.answers[q.id]||[]).map((v,j)=>`Lacuna ${j+1}: ${v||'—'}`).join('\n'):a.answers[q.id]||'Sem resposta')}</div>${q.type==='multiple'?`<p class="rubric">Corretas: ${(q.corrects||[]).map(n=>'ABCDEF'[n]).join(', ')}. Pontos: ${automaticPoints(q,a.answers[q.id]).toLocaleString('pt-BR',{maximumFractionDigits:3})}/${q.points}. Não marcadas: ${multipleBreakdown(q,a.answers[q.id]).missed}; erradas marcadas: ${multipleBreakdown(q,a.answers[q.id]).wrong}.</p>`:q.type==='blanks'?`<p class="rubric">Correção automática: ${automaticPoints(q,a.answers[q.id]).toLocaleString('pt-BR',{maximumFractionDigits:3})}/${q.points}. ${(q.blanks||[]).map((b,j)=>`Lacuna ${j+1}: ${esc(b.accepted.join(' / '))}`).join('; ')}.</p>`:q.type==='choice'?`<p class="rubric">Correta: ${'ABCDEF'[q.correct]}) ${esc(q.options[q.correct])} · ${a.answers[q.id]===q.correct?q.points:0}/${q.points} ponto(s).</p>`:`<label for="manual-${q.id}">Pontuação: 0 a ${q.points}</label><input type="number" id="manual-${q.id}" min="0" max="${q.points}" step="any" value="${r.manual?.[q.id]??''}" ${a.status==='active'?'disabled':''}>`}<p class="rubric pre">${esc(q.rubric||'Sem comentário adicional cadastrado.')}</p>${q.type==='open'?`<p class="muted">${gradingConfig(exam).mode==='numeric'?`Valor máximo na nota: ${(q.points/max*gradingConfig(exam).max).toLocaleString('pt-BR',{maximumFractionDigits:3})} de ${gradingConfig(exam).max}.`:`Peso desta questão: ${(q.points/max*100).toLocaleString('pt-BR',{maximumFractionDigits:1})}% da avaliação por conceito.`}</p><label for="qfeedback-${q.id}">Feedback desta questão</label><textarea id="qfeedback-${q.id}" maxlength="2000" style="min-height:100px" ${a.status==='active'?'disabled':''}>${esc(r.questionFeedback?.[q.id]||'')}</textarea>`:''}</details>`).join('')}<div class="card"><h2>Ocorrências (${d.events.length})</h2><p class="muted">Horários e durações do aparelho são informados pelo cliente. Recepção: servidor. Eventos de retorno complementam as saídas e não representam infrações adicionais.</p>${d.eventsTruncated?'<p>Limite de exibição: 2.000 eventos. Consulte o banco para os demais.</p>':''}<div class="event-list">${d.events.map(e=>`<label class="event selected-event"><input data-event="${esc(e.id)}" type="checkbox" ${(r.eventIds||[]).includes(e.id)?'checked':''}><span><strong>${esc(labels[e.type]||e.type)}</strong><br>Recebido: ${date(e.receivedAt)}<br><small>Aparelho: ${date(e.clientAt)} · Questão ${Math.max(0,qs.findIndex(q=>q.id===e.question))+1}${e.duration?' · '+(e.duration/1000).toFixed(1)+' s desde a saída':''}</small></span></label>`).join('')||'<p>Nenhum evento recebido. Isso não garante ausência de consulta.</p>'}</div></div>${a.status!=='active'?`<div class="card"><h2>Resultado e devolutiva</h2><p class="muted">Peso total: ${max}. Descontos são decisões do professor, sem aplicação automática por evento.</p><label for="deduction">Desconto total (0 a ${max})</label><input type="number" id="deduction" min="0" max="${max}" step="any" value="${r.deduction||0}"><label for="reason">Justificativa do desconto</label><textarea id="reason" maxlength="1000" style="min-height:95px">${esc(r.reason||'')}</textarea><label for="feedback">Devolutiva ao estudante</label><textarea id="feedback" maxlength="3000" style="min-height:110px">${esc(r.feedback||'')}</textarea><label class="check"><input type="checkbox" id="publish" ${r.published?'checked':''}> Publicar resultado e devolutiva</label><p id="preview-grade" class="notice"></p><button id="review">Salvar revisão</button></div>`:''}<details class="card"><summary>Histórico de revisões (${d.reviews.length})</summary>${d.reviews.map(x=>`<p>${date(x.at)} · ${esc(x.action||('Resultado '+resultText(x)+' · desconto '+x.deduction))}<br>${esc(x.reason||'')}<br><small>Responsável: ${esc(x.by)}</small></p>`).join('')||'<p>Nenhuma revisão.</p>'}</details>`;on('back',()=>dashboard());on('release',async()=>{await call('releaseSession',{uid});toast('Retomada liberada.');});if(a.status!=='active'){const manual=()=>Object.fromEntries(qs.filter(q=>q.type==='open').map(q=>[q.id,Number($('manual-'+q.id).value)]));const preview=()=>{const g=localGrade(exam,a.answers,manual(),Number($('deduction').value));$('preview-grade').textContent=`Prévia: ${gradingConfig(exam).mode==='numeric'?'nota':'conceito'} ${resultText(g)} · ${g.percent.toFixed(1)}% · ${g.total.toFixed(2)}/${g.totalMax}. Preencha todas as notas antes de salvar.`;};document.querySelectorAll('input[type=number]').forEach(x=>x.oninput=preview);preview();on('review',async()=>{for(const q of qs.filter(q=>q.type==='open'))if($('manual-'+q.id).value==='')throw Error('Preencha todas as notas abertas.');await call('reviewAttempt',{uid,manual:manual(),questionFeedback:Object.fromEntries(qs.filter(q=>q.type==='open').map(q=>[q.id,$('qfeedback-'+q.id).value])),deduction:Number($('deduction').value),reason:$('reason').value,feedback:$('feedback').value,published:$('publish').checked,eventIds:[...document.querySelectorAll('[data-event]:checked')].map(x=>x.dataset.event)});toast('Revisão salva com histórico.');await detail(uid);});}}
function exportCSV(){const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const text='\ufeff'+[['Avaliação','Disciplina','Dia','Turma','Nome','Email','Estado','Forma de avaliação','Resultado','Aproveitamento %','Desconto','Justificativa'],...rows.map(a=>[exam.title,exam.subject,exam.date,exam.group,a.name,a.email,a.status,gradingConfig(exam).mode==='numeric'?'Nota':'Conceito',a.review?resultText(a.review):'',a.review?.percent??'',a.review?.deduction||0,a.review?.reason||''])].map(row=>row.map(safe).join(';')).join('\r\n');const u=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8;'})),el=document.createElement('a');el.href=u;el.download='resultados-avaliacao.csv';el.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast(`Exportadas ${rows.length} tentativas carregadas.`);}
