function demoImportDecision(row,subjectId,group){if(row.issue)return{action:'skip',label:row.issue};const sub=demoDB.catalog.subjects.find(s=>s.id===subjectId),p=Object.values(demoDB.profiles).find(x=>x.email===row.email),en=demoDB.enrollments.find(x=>x.email===row.email&&x.subjectId===subjectId),pending=demoDB.pendingRoster?.find(x=>x.email===row.email&&x.subjectId===subjectId&&x.status==='waiting');if(p&&(p.role!=='student'||p.campusId!==sub.campusId||p.institutionId!==sub.institutionId))return{action:'skip',label:'Cadastro incompatível com este campus ou perfil'};if(p&&['rejected','suspended'].includes(p.status))return{action:'skip',label:'Cadastro rejeitado ou suspenso'};if(en)return{action:'skip',label:en.group===group&&en.active?'Já matriculado nesta turma':'Matrícula em outra turma ou inativa; revisar individualmente'};if(pending&&pending.group!==group)return{action:'skip',label:'Matrícula preparada em outra turma'};return p?.status==='active'?{action:'enroll',label:'Criar matrícula ativa'}:{action:'wait',label:'Preparar matrícula; aguardar cadastro/aprovação'};}
