function publicLink(key,value){const u=new URL(location.href);u.search='';u.hash='';u.searchParams.set(key,value);return u.href;}
function applyBrand(b){document.documentElement.style.setProperty('--brand-primary',b?.primary||'#254b3c');document.documentElement.style.setProperty('--brand-accent',b?.accent||'#dbe9a5');let box=$('institution-brand');if(!box){box=document.createElement('div');box.id='institution-brand';app.before(box);}box.innerHTML=b?`${b.logoUrl?`<img src="${esc(b.logoUrl)}" alt="Logotipo" loading="lazy">`:''}<div><strong>${esc(b.name)}</strong><small>${esc(b.tagline)}</small></div>`:'';}
async function publicRoute(){const params=new URLSearchParams(location.search);if(params.has('certificado')){const r=await call('verifyCertificate',{code:params.get('certificado')});certificatePage(r.certificate,true);return true;}if(params.has('curso')){const r=await call('getPublicCourse',{courseId:params.get('curso')});applyBrand(r.brand);publicCoursePage(r.course);return true;}if(params.has('instituicao')){const r=await call('getPublicCatalog',{institutionId:params.get('instituicao')});applyBrand(r.brand);app.innerHTML=`<h1>${esc(r.brand.name)}</h1><p class="lead">${esc(r.brand.tagline)}</p><h2>Cursos disponíveis</h2><div class="course-grid">${r.courses.map(c=>`<article class="card">${c.coverUrl?`<img class="course-cover" src="${esc(c.coverUrl)}" alt="Capa do curso">`:''}<h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><span class="pill">${c.free?'Gratuito':'Pago'}</span><p>${esc(c.ownerName)}</p><a href="${esc(publicLink('curso',c.id))}">Conhecer curso</a></article>`).join('')||'<p>Nenhum curso publicado.</p>'}</div>`;return true;}return false;}
function marketingHtml(c){const m=c.marketing||{};return `<section class="card course-presentation">${m.coverUrl?`<img class="course-cover" src="${esc(m.coverUrl)}" alt="Capa do curso" loading="lazy">`:''}<p class="eyebrow">${esc(m.duration||'Aprenda no seu ritmo')}</p>${m.goals?`<h2>O que você vai aprender</h2><p class="pre">${esc(m.goals)}</p>`:''}${m.audience?`<h3>Para quem é este curso</h3><p class="pre">${esc(m.audience)}</p>`:''}${m.teacherBio?`<h3>Conheça o professor</h3><p class="pre">${esc(m.teacherBio)}</p>`:''}</section>`;}
function publicCoursePage(c){app.innerHTML=`<span class="eyebrow">Conheça o curso</span><h1>${esc(c.title)}</h1><p class="lead">${esc(c.description)}</p><p>Com ${esc(c.ownerName)}</p>${marketingHtml(c)}<section class="card"><h2>Programa do curso</h2>${(c.learning?.modules||[]).map(m=>`<h3>${esc(m.title)}</h3><ul>${m.lessons.map(l=>`<li>${esc(l.title)}${l.preview?' · Aula demonstrativa':''}</li>`).join('')}</ul>`).join('')||c.subjects.map(s=>`<p>${esc(s.name)}</p>`).join('')}<p>${c.free?'Curso gratuito':Object.keys(CYCLES).map(k=>`${CYCLE_LABELS[k]}: ${money(c.billingPrices[k])}`).join(' · ')}</p><button id="public-enroll">${user?'Acessar curso':'Entrar para se matricular'}</button></section>${courseLessons(c).filter(l=>l.preview).map(l=>`<article class="card"><span class="pill">Aula demonstrativa</span><h2>${esc(l.title)}</h2><div class="pre">${esc(l.body||'')}</div>${l.url?`<a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">Abrir demonstração</a>`:''}</article>`).join('')}`;on('public-enroll',async()=>{if(!user){if(!config.enabled)throw Error('Configure o Firebase para usar a matrícula real.');return window.firebaseLogin();}await loadContext();await coursePage(c.id);});}
function courseEditor(existing=null){baseCourseEditor(existing);courseDraft=structuredClone(existing?.learning||{modules:[],certificate:{enabled:false,hours:1,minProgress:100,minPercent:60,requireAssessment:false}});const m=existing?.marketing||{};const el=document.createElement('div');el.id='course-extra';el.innerHTML=`<section class="card"><h2>Apresentação e divulgação</h2><label for="course-goals">Objetivos e benefícios</label><textarea id="course-goals" maxlength="4000">${esc(m.goals)}</textarea><label for="course-audience">Público-alvo</label><textarea id="course-audience" maxlength="2000">${esc(m.audience)}</textarea><label for="course-duration">Duração apresentada</label><input id="course-duration" maxlength="120" value="${esc(m.duration)}"><label for="course-bio">Apresentação do professor</label><textarea id="course-bio" maxlength="2000">${esc(m.teacherBio)}</textarea><label for="course-cover">Endereço da imagem de capa (HTTP/HTTPS)</label><input id="course-cover" type="url" value="${esc(m.coverUrl)}"><label for="course-group">Turma das avaliações do curso</label><input id="course-group" maxlength="80" value="${esc(existing?.group||'Curso')}"></section><section class="card"><h2>Módulos e aulas</h2><p>As aulas são organizadas em módulos. Marque uma aula como demonstrativa para divulgá-la publicamente. O progresso é registrado pelo próprio aluno ao concluir cada aula.</p><div id="modules-editor"></div><button id="module-add" class="outline" type="button">Adicionar módulo</button></section><section class="card"><h2>Certificado de conclusão</h2><label class="check"><input type="checkbox" id="cert-enabled" ${courseDraft.certificate.enabled?'checked':''}>Habilitar certificado verificável</label><label for="cert-hours">Carga horária</label><input id="cert-hours" type="number" min="0" max="5000" step="0.5" value="${courseDraft.certificate.hours}"><label for="cert-progress">Progresso mínimo nas aulas (%)</label><input id="cert-progress" type="number" min="1" max="100" value="${courseDraft.certificate.minProgress}"><label class="check"><input type="checkbox" id="cert-require" ${courseDraft.certificate.requireAssessment?'checked':''}>Exigir aproveitamento nas avaliações individuais publicadas vinculadas ao curso</label><label for="cert-percent">Aproveitamento mínimo em cada avaliação (%)</label><input id="cert-percent" type="number" min="0" max="100" value="${courseDraft.certificate.minPercent}"></section>`;$('course-save').before(el);drawModules();on('module-add',()=>{captureModules();if(courseDraft.modules.length>=30)throw Error('Limite de 30 módulos.');courseDraft.modules.push({title:'Novo módulo',subjectId:allowedSubjects()[0]?.id||'',lessons:[]});drawModules();});}
function captureModules(){courseDraft.modules.forEach((m,i)=>{m.title=$('module-title-'+i).value.trim();m.subjectId=$('module-subject-'+i).value;m.lessons.forEach((l,j)=>{l.title=$(`lesson-title-${i}-${j}`).value.trim();l.body=$(`lesson-body-${i}-${j}`).value;l.url=$(`lesson-url-${i}-${j}`).value.trim();l.preview=$(`lesson-preview-${i}-${j}`).checked;});});}
function drawModules(){$('modules-editor').innerHTML=courseDraft.modules.map((m,i)=>`<details class="card" open><summary>Módulo ${i+1}: ${esc(m.title)}</summary><label for="module-title-${i}">Título do módulo</label><input id="module-title-${i}" maxlength="150" value="${esc(m.title)}"><label for="module-subject-${i}">Disciplina (selecione-a também no curso)</label><select id="module-subject-${i}">${subjectOptions(m.subjectId)}</select><div class="actions"><button class="outline" data-module-up="${i}" ${i===0?'disabled':''}>Subir módulo</button><button class="outline" data-module-remove="${i}">Remover módulo</button><button class="outline" data-lesson-add="${i}">Adicionar aula</button></div>${m.lessons.map((l,j)=>`<div class="lesson-edit"><label for="lesson-title-${i}-${j}">Aula ${j+1}</label><input id="lesson-title-${i}-${j}" maxlength="150" value="${esc(l.title)}"><textarea id="lesson-body-${i}-${j}" rows="5" maxlength="30000" aria-label="Texto da aula">${esc(l.body)}</textarea><label for="lesson-url-${i}-${j}">Material complementar</label><input id="lesson-url-${i}-${j}" type="url" value="${esc(l.url)}"><label class="check"><input type="checkbox" id="lesson-preview-${i}-${j}" ${l.preview?'checked':''}>Aula demonstrativa pública</label><div class="actions"><button class="outline" data-lesson-up="${i}-${j}" ${j===0?'disabled':''}>Subir aula</button><button class="outline" data-lesson-remove="${i}-${j}">Remover aula</button></div></div>`).join('')}</details>`).join('');for(const[k,fn]of[['moduleUp',(i)=>{if(i>0)[courseDraft.modules[i-1],courseDraft.modules[i]]=[courseDraft.modules[i],courseDraft.modules[i-1]];}],['moduleRemove',i=>courseDraft.modules.splice(i,1)],['lessonAdd',i=>{if(courseLessons({learning:courseDraft}).length>=100)throw Error('Limite de 100 aulas.');courseDraft.modules[i].lessons.push({id:uuid(),title:'Nova aula',body:'',url:'',preview:false});}],['lessonRemove',(i,j)=>courseDraft.modules[i].lessons.splice(j,1)],['lessonUp',(i,j)=>{const a=courseDraft.modules[i].lessons;if(j>0)[a[j-1],a[j]]=[a[j],a[j-1]];}]]){const attr=k.replace(/[A-Z]/g,c=>'-'+c.toLowerCase());document.querySelectorAll(`[data-${attr}]`).forEach(b=>b.onclick=guard(()=>{captureModules();fn(...b.dataset[k].split('-').map(Number));drawModules();}));}}
function captureCourseExtras(){captureModules();courseDraft.certificate={enabled:$('cert-enabled').checked,hours:Number($('cert-hours').value),minProgress:Number($('cert-progress').value),minPercent:Number($('cert-percent').value),requireAssessment:$('cert-require').checked};const marketing={goals:$('course-goals').value,audience:$('course-audience').value,duration:$('course-duration').value,teacherBio:$('course-bio').value,coverUrl:$('course-cover').value.trim()},ids=[...document.querySelectorAll('[data-course-subject]:checked')].map(x=>x.dataset.courseSubject);if(!validMarketing(marketing)||!validLearning(courseDraft,ids))throw Error('Confira módulos, disciplinas selecionadas, links e critérios do certificado.');return{marketing,learning:structuredClone(courseDraft),group:$('course-group').value.trim()||'Curso'};}
async function enhanceCoursePage(r){const c=r.course;learningCourse=c;const extra=document.createElement('div');extra.id='course-learning';extra.innerHTML=`${marketingHtml(c)}${c.academic?`<section class="card"><h2>Período do curso</h2><p>${day(c.academic.start)} a ${day(c.academic.end)}</p>${c.academic.periods.map(p=>`<p>${esc(p.label)} · ${day(p.start)} a ${day(p.end)}</p>`).join('')}</section>`:''}<section class="card"><h2>Compartilhar curso</h2><p>Código: <strong>${esc(c.id)}</strong></p><input readonly aria-label="Link público do curso" value="${esc(publicLink('curso',c.id))}">${r.staff?'<p>Use este código no campo Vincular a um curso do editor de avaliações.</p><div class="actions"><button id="course-report">Painel de aprendizagem</button><button id="course-exam-new" class="outline">Criar avaliação do curso</button><button id="course-offers" class="outline">Cupons e bolsas</button></div>':''}</section><div id="learning-panel"></div>`;app.append(extra);on('course-report',()=>reportPanel(c.id));on('course-exam-new',()=>{if(!teacherView||c.ownerId!==user.uid)throw Error('Use o perfil do professor responsável.');selectedSubjectId=c.subjects[0].subjectId;editor();editing.courseId=c.id;editing.group=c.group||'Curso';drawEditor();});on('course-offers',()=>offersPanel(c.id));if(!r.access){if(profile?.role==='student'){const cert=await call('getMyCertificate',{courseId:c.id});if(cert.certificate){const b=document.createElement('button');b.textContent='Consultar certificado já emitido';b.onclick=()=>certificatePage(cert.certificate);extra.append(b);}}$('learning-panel').innerHTML=courseLessons(c).filter(l=>l.preview).map(l=>`<section class="card"><span class="pill">Aula demonstrativa</span><h3>${esc(l.title)}</h3><p class="pre">${esc(l.body||'')}</p>${l.url?`<a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">Abrir material</a>`:''}</section>`).join('');return;}if(profile?.role==='student'){learningState=await call('getLearning',{courseId:c.id});renderLearningPanel(c,learningState);}else $('learning-panel').innerHTML=outlineHtml(c,[],true);}
function outlineHtml(c,completed=[],staff=false){return(c.learning?.modules||[]).map(m=>`<section class="card"><h2>${esc(m.title)}</h2>${m.lessons.map(l=>`<details class="lesson-item"><summary>${completed.includes(l.id)?'✓ ':''}${esc(l.title)}</summary><div class="pre course-body">${esc(l.body||'')}</div>${l.url?`<p><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">Abrir material complementar</a></p>`:''}${!staff?`<button class="outline" data-complete-lesson="${esc(l.id)}" data-done="${!completed.includes(l.id)}">${completed.includes(l.id)?'Marcar como pendente':'Concluir aula'}</button>`:''}</details>`).join('')}</section>`).join('');}
function renderLearningPanel(c,state){$('learning-panel').innerHTML=!state.enrollment?'<div class="card"><h2>Comece sua jornada</h2><button id="course-join">Matricular-me no curso</button></div>':`<section class="card"><h2>Meu progresso</h2><progress max="100" value="${state.progress.percent}"></progress><p>${state.progress.done} de ${state.progress.total} aulas concluídas · ${state.progress.percent.toFixed(0)}%</p></section>${outlineHtml(c,state.enrollment.completed||[])}<section class="card"><h2>Avaliações e atividades do curso</h2>${state.exams.map(e=>`<div class="lesson-item"><strong>${esc(e.title)}</strong><p>${esc(e.subject)} · ${day(e.date)} · ${e.status?esc(e.status):'Pendente'}${e.percent!==null?' · '+e.percent.toFixed(1)+'%':''}</p>${e.mode==='live'?`<p>O professor informará o código da sessão ao vivo.</p>`:`<button class="outline" data-course-exam="${esc(e.id)}">Acessar avaliação</button>`}</div>`).join('')||'<p>Nenhuma avaliação publicada.</p>'}${state.truncated?'<p>Lista limitada a 100 atividades.</p>':''}</section>${c.learning?.certificate?.enabled?`<section class="card"><h2>Certificado</h2><p>Critérios: ${c.learning.certificate.minProgress}% das aulas${c.learning.certificate.requireAssessment?' e '+c.learning.certificate.minPercent+'% em cada avaliação individual publicada':''}.</p><label class="check"><input id="certificate-consent" type="checkbox">Autorizo meu nome no certificado e na consulta pública pelo código.</label><button id="certificate-issue">Emitir / consultar certificado</button></section>`:''}`;on('course-join',async()=>{await call('joinCourse',{courseId:c.id});await coursePage(c.id);});document.querySelectorAll('[data-complete-lesson]').forEach(b=>b.onclick=guard(async()=>{await call('completeLesson',{courseId:c.id,lessonId:b.dataset.completeLesson,done:b.dataset.done==='true'});await coursePage(c.id);}));document.querySelectorAll('[data-course-exam]').forEach(b=>b.onclick=guard(async()=>{exam=await call('getExam',{examId:b.dataset.courseExam});qs=exam.questions;await welcome();}));on('certificate-issue',async()=>{if(!$('certificate-consent').checked)throw Error('Confirme a publicação do nome para emitir o certificado.');const r=await call('issueCertificate',{courseId:c.id,publicNameConsent:true});certificatePage(r.certificate);});}
function certificatePage(c,verified=false){app.innerHTML=`<div class="certificate-actions actions">${commerceBack()}<button id="certificate-print">Imprimir / salvar em PDF</button></div><article id="certificate-sheet"><p class="eyebrow">${verified?'Autenticidade confirmada':'Conclusão de curso'}</p><h1>Certificado</h1><p>Certificamos que</p><h2>${esc(c.studentName)}</h2><p>concluiu o curso</p><h2>${esc(c.courseTitle)}</h2><p>Carga horária: ${c.hours} hora(s)</p><p>${esc(c.institution)}<br>Professor responsável: ${esc(c.teacherName)}</p><p>Emitido em ${date(c.issuedAtMs)}</p><p>Código de verificação: <strong>${esc(c.code)}</strong></p><p><a href="${esc(publicLink('certificado',c.code))}">Verificar autenticidade</a></p></article>`;bindCommerceBack();on('certificate-print',()=>window.print());}
