function addBankControls(){if(myModuleFeatures?.questionBank===false)return;const div=document.createElement('div');div.className='actions';div.innerHTML=`<button id="exam-bank-open" class="outline">Reutilizar questão do banco</button>`;$('question-editor').before(div);on('exam-bank-open',()=>{captureEditor();return bankPanel(true);});editing.questions.forEach((q,i)=>{const box=document.createElement('div');box.className='bank-save';box.innerHTML=`<label for="bank-topic-${i}">Assunto da questão</label><input id="bank-topic-${i}" maxlength="120" value="${esc(q.topic||'')}"><label for="bank-difficulty-${i}">Dificuldade</label><select id="bank-difficulty-${i}"><option value="easy">Fácil</option><option value="medium">Média</option><option value="hard">Difícil</option></select><button type="button" class="outline" id="bank-save-${i}">Salvar questão ${i+1} no banco</button>`;$('rubric-'+i).after(box);on('bank-save-'+i,async()=>{captureEditor();const topic=$('bank-topic-'+i).value.trim();if(!topic)throw Error('Informe o assunto.');const bankQuestion={...structuredClone(q),topic};if(!(editing.attemptCount>0))q.topic=topic;await call('saveBankQuestion',{entry:{subjectId:editing.subjectId,topic,difficulty:$('bank-difficulty-'+i).value,question:bankQuestion}});toast('Questão salva no banco.');});});}
