async function brandEditor(){app.innerHTML=`${commerceBack()}<h1>Identidade institucional.</h1><label for="brand-institution">Instituição</label><select id="brand-institution">${catalog.institutions.map(i=>`<option value="${esc(i.id)}">${esc(i.name)}</option>`).join('')}</select><div id="brand-fields"></div>`;bindCommerceBack();const paint=()=>{const institution=catalog.institutions.find(i=>i.id===$('brand-institution').value),b=institution?.branding||{name:institution?.name||'',tagline:'',logoUrl:'',primary:'#254b3c',accent:'#dbe9a5'};$('brand-fields').innerHTML=`<div class="card"><label for="brand-name">Nome apresentado</label><input id="brand-name" maxlength="120" value="${esc(b.name)}"><label for="brand-tagline">Apresentação curta</label><input id="brand-tagline" maxlength="200" value="${esc(b.tagline)}"><label for="brand-logo">Endereço do logotipo</label><input id="brand-logo" type="url" value="${esc(b.logoUrl)}"><label for="brand-primary">Cor principal</label><input id="brand-primary" type="color" value="${b.primary}"><label for="brand-accent">Cor de destaque</label><input id="brand-accent" type="color" value="${b.accent}"><p>Página institucional: <a href="${esc(publicLink('instituicao',institution?.id))}">${esc(publicLink('instituicao',institution?.id))}</a></p><button id="brand-save">Salvar identidade</button></div>`;on('brand-save',async()=>{const brand={name:$('brand-name').value.trim(),tagline:$('brand-tagline').value,logoUrl:$('brand-logo').value.trim(),primary:$('brand-primary').value,accent:$('brand-accent').value};if(!validBrand(brand))throw Error('Confira os campos.');await call('saveBrand',{institutionId:institution.id,brand});institution.branding=brand;applyBrand(brand);toast('Identidade salva.');});};$('brand-institution').onchange=paint;paint();}
