function yearStudentsTable(rows){return `<div class="question-table"><table><tr><th>Aluno</th><th>Resultados por período / disciplina</th><th>Observações / advertências</th></tr>${rows.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.results?s.results.map(g=>`<p>${esc(g.periodLabel)} · ${esc(g.subjectId||'Geral')}: ${resultLabel(g)} — ${esc(g.authorName)}<br>${esc(g.notes)}</p>`).join(''):s.result?esc(s.result.concept??s.result.numericGrade??s.result.percent):esc(s.status||'Sem resultado')}</td><td>${s.observations??'—'} / ${s.warnings??'—'}</td></tr>`).join('')}</table></div>`;}
